var Q11 = [
{n:1, q:'El Derecho Penal español....', o:{a:'Se contiene en el Código Penal y en las denominadas Leyes Penales Especiales.',b:'Se puede definir como el conjunto de normas jurídico positivas reguladoras del poder punitivo del Estado, que definen como delitos o estados peligrosos determinados presupuestos a los que se asignan ciertas consecuencias jurídicas denominadas penas o medidas de seguridad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Derecho Penal español se contiene tanto en el Código Penal como en leyes penales especiales, y se puede definir como el conjunto de normas del poder punitivo del Estado.'}},
{n:2, q:'El Código Penal vigente fue publicado por medio de la Ley Orgánica 10/1995 y contiene:', o:{a:'Un Título Preliminar y dos Libros.',b:'Un Preámbulo, un Título Preliminar y tres Libros.',c:'Una Exposición de motivos, un Preámbulo y dos Libros.',d:'Un Título Preliminar y tres Libros.'}, correct:'a', why:{a:'El CP vigente LO 10/1995 contiene un Título Preliminar y dos Libros (Libro I y Libro II), no tres.'}},
{n:3, q:'En el Código Penal vigente (LO 10/95) podemos distinguir entre:', o:{a:'Parte Ordinaria y Parte Extraordinaria.',b:'Parte General y Parte Especial.',c:'Parte Penal y Parte Procesal.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El CP se divide en Parte General (Libro I) y Parte Especial (Libro II).'}},
{n:4, q:'La parte general en el Código Penal vigente (LO 10/95):', o:{a:'Se extiende a lo largo del Título Preliminar y el Libro I.',b:'Comprende el Título Preliminar y los dos primeros capítulos del Libro I.',c:'Comprende el Título Preliminar y los Libros I y II.',d:'Se halla contenida en el Título Preliminar.'}, correct:'a', why:{a:'La parte general comprende el Título Preliminar y el Libro I del Código Penal.'}},
{n:5, q:'La parte especial en el Código penal vigente (LO 10/95):', o:{a:'Está contenida en el Título Preliminar.',b:'Comprende los Libros II y III.',c:'Se halla contenida en el Libro I.',d:'Se corresponde con el Libro II.'}, correct:'d', why:{d:'La parte especial del CP está contenida en el Libro II.'}},
{n:6, q:'"De las garantías penales y de la aplicación de la Ley Penal" es la denominación de:', o:{a:'El Libro I del Código Penal.',b:'El Título Preliminar del Código Penal.',c:'El Libro II del Código Penal.',d:'El Libro III del Código Penal.'}, correct:'b', why:{b:'"De las garantías penales y de la aplicación de la Ley Penal" es la denominación del Título Preliminar del CP.'}},
{n:7, q:'El Título Preliminar del Código Penal vigente (LO 10/95):', o:{a:'Comprende los artículos 1 a 29.',b:'Comprende los artículos 1 a 19.',c:'Comprende los artículos 1 a 9.',d:'Comprende los artículos 1 a 11.'}, correct:'c', why:{c:'El Título Preliminar del CP comprende los artículos 1 a 9.'}},
{n:8, q:'"Disposiciones Generales sobre los delitos, las personas responsables, las penas, medidas de seguridad y demás consecuencias del acto ilícito penal."', o:{a:'Es el epígrafe del Título Preliminar del Código Penal vigente.',b:'Es el epígrafe del Libro I del Código Penal vigente.',c:'Es el epígrafe del Libro II del Código Penal vigente.',d:'Es el epígrafe del Libro III del Código Penal vigente.'}, correct:'b', why:{b:'Esa frase es el epígrafe del Libro I del Código Penal vigente.'}},
{n:9, q:'El Libro I del Código Penal vigente (LO 10/95):', o:{a:'Comprende los artículos 10 a 137.',b:'Comprende los artículos 11 a 135.',c:'Comprende los artículos 12 a 135.',d:'Comprende los artículos 20 a 137.'}, correct:'a', why:{a:'El Libro I del CP comprende los artículos 10 a 137.'}},
{n:10, q:'El Libro II del Código Penal vigente (LO 10/95), lleva por título:', o:{a:'Faltas y sus penas.',b:'Delitos y sus penas.',c:'De las garantías penales y de la aplicación de la Ley Penal.',d:'Delitos Leves y sus penas.'}, correct:'b', why:{b:'El Libro II del CP lleva por título "Delitos y sus penas".'}},
{n:11, q:'El Libro III del Código Penal vigente (LO 10/95) lleva por título:', o:{a:'Faltas y sus penas.',b:'Delitos y sus penas.',c:'De las garantías penales y de la aplicación de la Ley Penal.',d:'El Libro III fue derogado por la reforma operada por medio de la Ley Orgánica 1/2015.'}, correct:'d', why:{d:'El Libro III del CP fue derogado por la LO 1/2015, que eliminó las faltas e introdujo los delitos leves.'}},
{n:12, q:'Tras la reforma operada por la Ley Orgánica 1/2015, y con relación a las faltas, indique la respuesta correcta:', o:{a:'Las faltas han desaparecido de nuestro ordenamiento jurídico penal.',b:'Se han despenalizado algunas de las conductas que se castigaban como faltas en el Libro III del Código Penal.',c:'La mayoría de las conductas que se castigaban como faltas han pasado a ser delitos leves.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Tras la LO 1/2015, las faltas desaparecieron: parte se despenalizaron y parte pasaron a ser delitos leves.'}},
{n:13, q:'En el Código Penal vigente (LO 10/95), "De la infracción penal" es el epígrafe:', o:{a:'Del Título I, del Libro II.',b:'Del Título I, del Libro I.',c:'Del Título II, del Libro II.',d:'Del Título II, del Libro I.'}, correct:'b', why:{b:'"De la infracción penal" es el epígrafe del Título I del Libro I del CP.'}},
{n:14, q:'El Capítulo I, del Título I, del Libro I del Código Penal vigente (LO 10/95), lleva por título:', o:{a:'De los delitos.',b:'De la infracción penal.',c:'De los delitos y las penas.',d:'De la infracción penal y las penas.'}, correct:'a', why:{a:'El Capítulo I del Título I del Libro I lleva por título "De los delitos".'}},
{n:15, q:'El Capítulo I, del Título I, del Libro I del Código Penal vigente (LO 10/95)...', o:{a:'Comprende los artículos 10 a 58.',b:'Comprende los artículos 10 a 48.',c:'Comprende los artículos 11 a 38.',d:'Comprende los artículos 10 a 18.'}, correct:'d', why:{d:'El Capítulo I del Título I del Libro I del CP comprende los artículos 10 a 18.'}},
{n:16, q:'El artículo 10 del Código Penal considera delitos...', o:{a:'Las acciones u omisiones penadas por la Ley.',b:'Las acciones u omisiones dolosas o imprudentes penadas por la Ley.',c:'Las acciones y omisiones dolosas o imprudentes penadas por la Ley.',d:'Las acciones y omisiones dolosas e imprudentes penadas por la Ley.'}, correct:'c', why:{c:'El art.10 CP dice exactamente: "Son delitos las acciones y omisiones dolosas o imprudentes penadas por la Ley". Usa "y", no "u".'}},
{n:17, q:'Para que una conducta pueda ser considerada delito debe producirse una acción u omisión:', o:{a:'Típica, antijurídica, responsable y punible.',b:'Típica, antijurídica, culpable y punible.',c:'Típica, antijurídica, responsable y atribuible.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'Los elementos del delito son tipicidad, antijuricidad, culpabilidad y punibilidad.'}},
{n:18, q:'El Derecho Penal Español es un derecho penal de acto y no de autor, por tanto:', o:{a:'Nunca pueden constituir delito ni el pensamiento, ni las ideas, ni siquiera la resolución de delinquir, en tanto no se traduzca en actos externos.',b:'Nunca pueden constituir delito los hechos producidos por animales, por más que puedan producir resultados lesivos.',c:'Nunca pueden constituir delito los sucesos puramente causales, como los fenómenos de la naturaleza, por más que puedan producir resultados lesivos.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'Todas las afirmaciones (a, b y c) son correctas consecuencias del principio de Derecho Penal de acto.'}},
{n:19, q:'La voluntad delictiva o acción penal se manifiesta con:', o:{a:'Una acción o una omisión.',b:'Una acción, una omisión o una transgresión.',c:'Una acción, una omisión o una comisión.',d:'Una acción, una omisión o una comisión por omisión.'}, correct:'a', why:{a:'La acción penal se manifiesta mediante una acción o una omisión.'}},
{n:20, q:'En el ámbito del Derecho Penal, la conducta activa que supone un movimiento corporal que produce en el mundo exterior un resultado consistente en un peligro o lesión para el bien jurídicamente protegido, se denomina:', o:{a:'Acción.',b:'Omisión.',c:'Comisión.',d:'Excusa absolutoria.'}, correct:'a', why:{a:'La conducta activa con movimiento corporal y resultado en el mundo exterior es la Acción.'}},
{n:21, q:'En el ámbito del Derecho Penal, la conducta pasiva que consiste en no hacer aquello que se esperaba del sujeto, se denomina:', o:{a:'Omisión.',b:'Acción.',c:'Comisión por omisión.',d:'Negligencia.'}, correct:'a', why:{a:'La conducta pasiva de no hacer lo que se esperaba del sujeto es la Omisión.'}},
{n:22, q:'En el ámbito del Derecho Penal, cuando el sujeto no realiza aquello que estaba obligado a realizar, y se produce un resultado lesivo para el bien jurídicamente protegido:', o:{a:'Estaremos ante una comisión por omisión.',b:'El sujeto que omite responde como si hubiera producido el daño mediante una conducta activa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La comisión por omisión implica que quien no actúa estando obligado responde como si hubiera actuado activamente.'}},
{n:23, q:'Juan es contratado por los padres de un bebé para que lo vigile mientras ellos se van a cenar. Cuando regresan encuentran a Juan borracho y comprueban que el bebé se ha caído de la cama produciéndose graves lesiones. Teniendo en cuenta lo anterior, entendemos que Juan podría ser autor de un delito al haberse producido:', o:{a:'Una conducta activa o comisión.',b:'Una conducta inactiva u omisión.',c:'Una comisión por omisión.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'Juan tenía posición de garante y no actuó, causando el resultado, lo que constituye comisión por omisión.'}},
{n:24, q:'En el delito de homicidio del artículo 138 del Código Penal, que castiga al que matare a otro, y cuya acción consiste en matar, que el resultado es la persona muerta y que la lesión se ha producido contra un bien jurídico protegido, que es la vida de una persona, el sujeto ha realizado:', o:{a:'Una conducta activa o comisión.',b:'Una conducta inactiva u omisión.',c:'Una comisión por omisión.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El homicidio del art.138 CP es una conducta activa (comisión): el sujeto actúa positivamente para matar.'}},
{n:25, q:'En el delito contenido en el artículo 195 del Código Penal que castiga a quien no socorriese a una persona que se halle desamparada y en peligro manifiesto y grave, cuando pudiere hacerlo sin riesgo propio ni de terceros, el sujeto ha realizado:', o:{a:'Una conducta activa o comisión.',b:'Una conducta inactiva u omisión.',c:'Una comisión por omisión.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El delito de omisión del deber de socorro (art.195 CP) es una omisión pura: el sujeto no actúa.'}},
{n:26, q:'De acuerdo con lo previsto en el art.11 del Código Penal, los delitos que consistan en la producción de un resultado solo se entenderán cometidos por omisión cuando la no evitación del mismo, al infringir un especial deber jurídico del autor, equivalga, según el sentido del texto de la ley, a su causación. A tal efecto se equipara la omisión a la acción:', o:{a:'Cuando el omitente haya creado una ocasión de riesgo para el bien jurídicamente protegido mediante una acción u omisión precedente.',b:'Cuando exista una específica obligación legal o contractual de actuar.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.11 CP equipara la omisión a la acción cuando hay fuente de riesgo creada por el omitente o cuando existe obligación legal o contractual de actuar.'}},
{n:27, q:'En la piscina de una urbanización se está ahogando una persona y no acuden a socorrerla ni los bañistas que se encuentran en el lugar, ni Andrés, que es el socorrista de la piscina. Teniendo en cuenta lo establecido en el art.11 del Código Penal...', o:{a:'El socorrista es considerado responsable porque tiene una obligación contractual que le obliga a intervenir.',b:'No responden el resto de bañistas porque en ellos no concurre una obligación contractual que obliga a intervenir.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El socorrista responde por comisión por omisión (obligación contractual). Los bañistas, si no socorren, responden por omisión del deber de socorro (art.195 CP), no por comisión por omisión.'}},
{n:28, q:'Un camionero observa que pierde parte de la carga en una curva peligrosa y sigue su camino sin tomar ninguna medida y, momentos después, un vehículo colisiona contra la citada carga y muere uno de sus ocupantes. Al producirse el resultado de muerte y teniendo en cuenta lo establecido en el art.11 del código Penal...', o:{a:'El camionero responde de un delito de homicidio, como si hubiera llevado a cabo la acción de matar.',b:'El camionero es considerado responsable porque tiene una obligación contractual que le obliga a intervenir.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El camionero creó una situación de riesgo precedente (pérdida de carga) y omitió evitar el resultado, respondiendo por homicidio en comisión por omisión según el art.11 CP.'}},
{n:29, q:'Para que exista delito es necesario que la acción u omisión que se pretende castigar sea:', o:{a:'Típica.',b:'Ejecutada dolosa o imprudentemente por una o varias personas físicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Para que exista delito la acción u omisión debe ser típica y ejecutada dolosa o imprudentemente.'}},
{n:30, q:'El artículo 1.1. del Código Penal dispone que...', o:{a:'No será castigada ninguna acción ni conducta que no esté prevista como delito o infracción administrativa, por ley anterior a su perpetración.',b:'No será castigada ninguna acción ni omisión que no esté prevista como delito o infracción administrativa, por ley anterior a su perpetración.',c:'No será castigada ninguna acción ni omisión que no esté prevista como delito o falta, por ley anterior a su perpetración.',d:'No será castigada ninguna acción ni omisión que no esté prevista como delito, por ley anterior a su perpetración.'}, correct:'d', why:{d:'El art.1.1 CP establece que no será castigada ninguna acción ni omisión que no esté prevista como delito por ley anterior a su perpetración.'}},
{n:31, q:'Se dice que una conducta es atípica...', o:{a:'Cuando coincide plenamente con el tipo descrito en la norma penal.',b:'Cuando coincide plena o parcialmente con el tipo descrito en la norma penal.',c:'Cuando no coincide con el tipo descrito en la norma penal.',d:'Cuando se lleva a cabo interviniendo culpa o negligencia.'}, correct:'c', why:{c:'Una conducta es atípica cuando no encaja en el tipo penal descrito en la norma.'}},
{n:32, q:'Teniendo en cuenta lo establecido en el art.185 del Código Penal, que castiga al que ejecutare o hiciere ejecutar a otra persona actos de exhibición obscena ante menores de edad o incapaces, si el acto de exhibicionismo se realiza ante personas mayores de edad, que no sean incapaces, se calificará como:', o:{a:'Conducta atípica.',b:'Conducta antijurídica no punible.',c:'Conducta típica no punible.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Si el exhibicionismo se realiza ante adultos capaces, no encaja en el tipo del art.185 CP, siendo conducta atípica.'}},
{n:33, q:'La antijuricidad de una acción u omisión supone...', o:{a:'Que debe ser contraria a alguno de los preceptos de la legislación penal.',b:'Que debe ser contraria al Derecho en su conjunto.',c:'Que debe estar prevista en una norma con rango de ley.',d:'Las respuestas a y c son correctas.'}, correct:'b', why:{b:'La antijuricidad supone que la conducta es contraria al Derecho en su conjunto, no solo a la norma penal.'}},
{n:34, q:'En el Derecho Penal, la culpabilidad supone...', o:{a:'Que la acción u omisión realizada debe ser contraria al Derecho en su conjunto.',b:'Que la acción u omisión debe estar descrita en la ley penal.',c:'Que la acción u omisión llevada a cabo por el sujeto le pueda ser atribuible a título de dolo o culpa.',d:'Que no concurra ninguna de las causas de justificación establecidas en la ley penal.'}, correct:'c', why:{c:'La culpabilidad supone que la acción u omisión puede ser atribuida al sujeto a título de dolo o culpa.'}},
{n:35, q:'El artículo 5 del Código Penal dispone que ...', o:{a:'No hay delito sin dolo o culpa.',b:'No hay delito sin dolo o imprudencia.',c:'No hay pena sin dolo o culpa.',d:'No hay pena sin dolo o imprudencia.'}, correct:'d', why:{d:'El art.5 CP dice textualmente: "No hay pena sin dolo o imprudencia". Usa "pena" (no "delito") e "imprudencia" (no "culpa").'}},
{n:36, q:'Señale la afirmación incorrecta:', o:{a:'Obra dolosamente el que realiza un delito con conciencia y voluntad.',b:'En el dolo se distingue entre un elemento intelectual y un elemento volitivo.',c:'Para que exista dolo es preciso que el sujeto quiera la acción y el resultado.',d:'Las acciones u omisiones dolosas sólo se castigarán cuando expresamente lo disponga la Ley.'}, correct:'d', why:{d:'Las acciones dolosas siempre se castigan. Es la imprudencia la que solo se castiga cuando expresamente lo dispone la ley (art.12 CP).'}},
{n:37, q:'Respecto al dolo, señale la afirmación incorrecta:', o:{a:'Dolo indirecto: el resultado de la acción que se realiza no es el fin último planeado por el responsable, pero sabe que esa determinada acción es necesaria para conseguir el fin planeado, por lo que, aun así, utiliza a otro para ejecutarla.',b:'Dolo directo de primer grado: el autor de la acción provoca un daño de manera voluntaria y el resultado de esta acción es el fin que quería conseguir el autor.',c:'Dolo directo de segundo grado: el resultado de la acción que el autor realiza no es el fin último planeado por dicho autor, pero este sabe que se producirá, pues esta acción es necesaria para conseguir el fin planeado. En un mismo acto se puede cometer más de un delito con dolo.',d:'Dolo eventual: se produce cuando, aunque el autor no desea un determinado resultado, tampoco descarta que éste se pueda producir como consecuencia de la acción que se propone realizar y, aun así, realiza dicha acción.'}, correct:'a', why:{a:'La descripción de la opción a no corresponde al dolo indirecto, sino a una figura diferente. El dolo indirecto o de segundo grado es cuando el resultado no deseado se acepta como consecuencia necesaria.'}},
{n:38, q:'La imprudencia punible es una infracción o negligencia causada por:', o:{a:'Una falta de previsión que provoca un daño a n tercero en un bien protegido por la ley.',b:'El incumplimiento de un deber de cuidado (un error que podría haberse evitado) y que provoca un daño a un tercero en un bien protegido por la ley.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La imprudencia punible se basa en el incumplimiento del deber de cuidado que provoca un daño evitable.'}},
{n:39, q:'En el Código Penal vigente (LO 10/95), las acciones u omisiones imprudentes:', o:{a:'Se castigan con la pena inferior en grado a la prevista para el delito doloso.',b:'Sólo se castigan cuando expresamente lo dispone la Ley.',c:'Se castigan con la pena inferior en uno o dos grados a la prevista para el delito doloso.',d:'Están previstas en la Legislación Penal Especial.'}, correct:'b', why:{b:'El art.12 CP establece que las acciones u omisiones imprudentes solo se castigarán cuando expresamente lo disponga la Ley.'}},
{n:40, q:'Nuestro Código Penal distingue entre imprudencia:', o:{a:'Grave y menos grave.',b:'Grave y muy grave.',c:'Grave y leve.',d:'Grave, leve y levísima.'}, correct:'a', why:{a:'Tras la reforma de la LO 1/2015, el CP distingue entre imprudencia grave y menos grave.'}},
{n:41, q:'Para distinguir la imprudencia grave de la imprudencia menos grave, será necesario tener en cuenta:', o:{a:'La mayor o menor falta de cuidado mostrada en la acción u omisión desencadenante del riesgo, atendidas las circunstancias concurrentes en cada caso.',b:'La mayor o menor previsibilidad del evento desencadenante del resultado.',c:'La mayor o menor gravedad de la infracción de ese deber de cuidado, según las normas socioculturales existentes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Para distinguir imprudencia grave de menos grave hay que atender a la falta de cuidado, la previsibilidad y la gravedad de la infracción del deber.'}},
{n:42, q:'En Derecho Penal, la punibilidad supone:', o:{a:'Que el acto tipificado en la ley como delito debe tener señalada una pena.',b:'Que la conducta debe ser atribuible al sujeto a título de dolo o imprudencia.',c:'Que la conducta debe ser contraria al derecho en su conjunto.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'La punibilidad supone que al acto tipificado como delito le corresponde una pena prevista en la ley.'}},
{n:43, q:'En Derecho Penal, los supuestos de exclusión de la punibilidad se denominan:', o:{a:'Circunstancias modificativas de la responsabilidad criminal.',b:'Excusas absolutorias.',c:'Delitos leves.',d:'Delitos imprudentes.'}, correct:'b', why:{b:'Los supuestos de exclusión de la punibilidad se denominan excusas absolutorias.'}},
{n:44, q:'Aquellas causas que no excluyen la antijuricidad ni la culpabilidad pero impiden la imposición de la pena se denominan:', o:{a:'Condiciones objetivas de punibilidad.',b:'Excusas absolutorias.',c:'Eximentes incompletas.',d:'Causas personales de exclusión de la pena.'}, correct:'b', why:{b:'Las excusas absolutorias son las causas que impiden la imposición de la pena sin excluir antijuricidad ni culpabilidad.'}},
{n:45, q:'En nuestro Código Penal, los delitos se clasifican en función de...', o:{a:'La pena con la que son castigados.',b:'El grado de participación de las personas responsables.',c:'Las circunstancias que concurren en el hecho.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Según el art.13 CP, los delitos se clasifican según la pena con la que son castigados.'}},
{n:46, q:'De conformidad con el art.13 del Código Penal, los delitos se clasifican en:', o:{a:'Graves, menos graves y leves.',b:'Graves, menos graves, imprudentes y leves.',c:'Graves, menos graves e imprudentes.',d:'Graves, imprudentes y leves.'}, correct:'a', why:{a:'El art.13 CP clasifica los delitos en graves, menos graves y leves.'}},
{n:47, q:'Son delitos menos graves las infracciones...', o:{a:'Que la ley castiga con penas leves o menos graves.',b:'Cometidas por imprudencia menos grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Son delitos menos graves los que la ley castiga con penas menos graves (art.13.2 CP).'}},
{n:48, q:'Son delitos leves las infracciones...', o:{a:'Que la ley castiga con penas leves.',b:'Que por su ejecución y circunstancias no producen un daño relevante para el bien jurídicamente protegido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Son delitos leves los que la ley castiga con penas leves (art.13.3 CP).'}},
{n:49, q:'Son delitos graves, las infracciones...', o:{a:'Dolosas que tengan señalada una pena superior en grado a la que correspondería al mismo delito cometido por imprudencia.',b:'Administrativas que supongan un daño relevante para el bien jurídicamente protegido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Son delitos graves los que la ley castiga con pena grave, independientemente de si son dolosos o imprudentes.'}},
{n:50, q:'Respecto a la clasificación de los delitos, el art.13 del Código Penal establece que:', o:{a:'Son delitos graves las infracciones que la Ley castiga con pena grave.',b:'Son delitos menos graves las infracciones que la Ley castiga con pena menos grave.',c:'Son delitos leves las infracciones que la ley castiga con pena leve.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.13 CP establece que los delitos se clasifican según la pena en graves, menos graves y leves.'}},
{n:51, q:'Cuando la pena, por su extensión, pueda incluirse a la vez entre las penas graves y menos graves, el delito se considerará, en todo caso, como:', o:{a:'Grave.',b:'Menos grave.',c:'Grave o menos grave, dependiendo de las circunstancias que concurran en el hecho.',d:'Doloso.'}, correct:'a', why:{a:'Cuando la pena puede incluirse entre graves y menos graves, el delito se considera en todo caso grave (art.13.4 CP).'}},
{n:52, q:'Cuando la pena, por su extensión, pueda considerarse como leve y como menos graves, el delito se considerará, en todo caso, como:', o:{a:'Grave.',b:'Menos grave.',c:'Leve.',d:'Doloso.'}, correct:'b', why:{b:'Cuando la pena puede considerarse leve y menos grave, el delito se considera en todo caso menos grave (art.13.4 CP).'}},
{n:53, q:'Según el art. 15 del Código Penal, son punibles:', o:{a:'El delito consumado y el delito frustrado.',b:'El delito consumado y la tentativa de delito.',c:'El delito consumado, el delito frustrado y la tentativa.',d:'El delito consumado, el delito frustrado, el delito agotado y la tentativa de delito.'}, correct:'b', why:{b:'El art.15 CP establece que son punibles el delito consumado y la tentativa de delito.'}},
{n:54, q:'Según STS de 17/03/1995, la consumación del delito se produce:', o:{a:'Cuando el tipo se ha realizado plenamente desde el punto de vista de la acción.',b:'Cuando el tipo se ha realizado plenamente desde el punto de vista del resultado.',c:'Cuando el tipo se ha realizado plenamente, tanto desde el punto de vista de la acción, como desde el punto de vista del resultado.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'La consumación se produce cuando el tipo penal se realiza plenamente desde la perspectiva de la acción y del resultado.'}},
{n:55, q:'Pedro acude a una vivienda ajena con intención de desvalijaria. Cuando ha forzado la puerta y se dispone a coger el dinero se arrepiente y se marcha de la vivienda sin apropiarse de nada. Teniendo en cuenta lo anterior, indique la respuesta correcta:', o:{a:'Pedro es autor de un delito de robo en grado de tentativa.',b:'Pedro no es autor de delito alguno.',c:'Pedro solo responde de los daños causados en la puerta.',d:'Pedro es autor de un delito de robo en grado de tentativa y de los daños causados en la puerta.'}, correct:'a', why:{a:'Pedro comenzó la ejecución del delito (forzó la puerta) pero no lo consumó. Es tentativa de robo con fuerza.'}},
{n:56, q:'Cuando el sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente debieran producir el resultado, y sin embargo éste no se produce por causas independientes de la voluntad del autor, estamos ante:', o:{a:'Delito consumado.',b:'Delito en grado de tentativa.',c:'Proposición.',d:'Conspiración.'}, correct:'b', why:{b:'La definición describe la tentativa de delito según el art.16 CP.'}},
{n:57, q:'Según el art.16.2 del Código Penal, queda exento de responsabilidad por el delito intentado quien evite voluntariamente su consumación, bien desistiendo de la ejecución ya iniciada, bien impidiendo la producción del resultado, sin perjuicio...', o:{a:'De la responsabilidad en que pudiera haber incurrido por los actos ejecutados, si estos fueran ya constitutivos de otro delito.',b:'De la responsabilidad civil que pudiera derivarse de los actos ya ejecutados, como así establece el art.17.3 de dicho código penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.16.2 CP exime de responsabilidad por el delito intentado al que desiste voluntariamente, sin perjuicio de la responsabilidad por otros delitos ya cometidos.'}},
{n:58, q:'Cuando en un hecho delictivo intervengan varios sujetos...', o:{a:'Quedarán exentos de responsabilidad penal por ese delito, aquel o aquellos que desistan de la ejecución ya iniciada y, además, impidan o intenten impedir, seria, firme y decididamente la consumación del mismo.',b:'Los actos ejecutados antes del desistimiento generan responsabilidad para quienes desistan, si fueren constitutivos de otro delito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'En caso de pluralidad de sujetos, el desistimiento exime solo a quien desiste e intenta impedir la consumación, sin perjuicio de responsabilidad por otros delitos ya cometidos.'}},
{n:59, q:'A los autores de tentativa de delito se les impondrá la pena:', o:{a:'Inferior en uno o dos grados a la señalada por la Ley para el delito consumado.',b:'Inferior en dos grados a la señalada por la Ley para el delito consumado.',c:'Inferior en uno o dos grados a la señalada por la Ley para el delito consumado.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art.62 CP dispone que a los autores de tentativa se les impondrá la pena inferior en uno o dos grados a la señalada para el delito consumado.'}},
{n:60, q:'Además de la tentativa y la consumación, también se castigan los llamados "actos preparatorios": la conspiración, la proposición y la provocación para delinquir, regulados en:', o:{a:'Los artículos 17 y 18 del Código Penal.',b:'Los artículos 18 a 23 del Código Penal.',c:'Los artículos 17 a 23 del Código Penal.',d:'Los artículos 18 y 19 del Código Penal.'}, correct:'a', why:{a:'Los actos preparatorios (conspiración, proposición y provocación) están regulados en los artículos 17 y 18 del CP.'}},
{n:61, q:'Cuando dos personas se conciertan para cometer un delito y deciden ejecutarlo, en el Código Penal se considera que dicha conducta constituye:', o:{a:'Provocación.',b:'Conspiración.',c:'Proposición.',d:'Tentativa.'}, correct:'b', why:{b:'Hay conspiración cuando dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo (art.17.1 CP).'}},
{n:62, q:'Conforme establece el art.17 del Código Penal...', o:{a:'Existe conspiración cuando dos o mas personas se conciertan para la ejecución de un delito y resuelven ejecutarlo.',b:'Existe proposición cuando el que ha resuelto cometer un delito invita a otra u otras personas a participar en él.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.17 CP define tanto la conspiración como la proposición tal como se describen en las opciones a y b.'}},
{n:63, q:'La conspiración y la proposición para delinquir...', o:{a:'Solo se castigan en los delitos dolosos con resultado lesivo.',b:'Solo se castigan en los casos especialmente previstos en la ley.',c:'Solo se castigan cuando una ley penal especial así lo disponga.',d:'Serán castigadas con la pena señalada al delito en su mitad inferior.'}, correct:'b', why:{b:'La conspiración y la proposición solo se castigan en los casos especialmente previstos por la ley (art.17.3 CP).'}},
{n:64, q:'Cuando directamente se incita por medio de la imprenta, la radiodifusión o cualquier otro medio de eficacia semejante, que facilite la publicidad, o ante una concurrencia de personas, a la perpetración de un delito, existe:', o:{a:'Conspiración para delinquir.',b:'Proposición para delinquir.',c:'Provocación para delinquir.',d:'Apología del delito.'}, correct:'c', why:{c:'La incitación directa pública a la perpetración de un delito es la provocación para delinquir (art.18.1 CP).'}},
{n:65, q:'La exposición ante una concurrencia de personas, o por cualquier medio de difusión, de ideas, o doctrinas que ensalcen el crimen o enaltezcan a su autor, es considerada en el Código Penal:', o:{a:'Conspiración para delinquir.',b:'Proposición para delinquir.',c:'Provocación para delinquir.',d:'Apología.'}, correct:'d', why:{d:'La exposición de ideas que ensalcen el crimen o a su autor es la apología, según el art.18.2 CP.'}},
{n:66, q:'De acuerdo con lo establecido en el artículo 18 del Código Penal, la apología solo será delictiva:', o:{a:'Como forma de provocación y si por su naturaleza y circunstancias constituye una incitación directa a cometer un delito.',b:'Como forma de conspiración y si por su naturaleza y circunstancias constituye una incitación directa a cometer un delito.',c:'Como forma de provocación y si por su naturaleza y circunstancias constituye una incitación directa o indirecta a cometer delitos.',d:'Como forma de conspiración y si por su naturaleza y circunstancias constituye una incitación directa o indirecta a cometer un delito.'}, correct:'a', why:{a:'El art.18.2 CP establece que la apología solo es delictiva como forma de provocación cuando constituye incitación directa a cometer un delito.'}},
{n:67, q:'De acuerdo con lo establecido en el artículo 18 del Código Penal:', o:{a:'La provocación se castigará exclusivamente en los casos en que la Ley así lo prevea.',b:'Si la provocación hubiese seguido la perpetración del delito, se castigará como inducción.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.18 CP establece que la provocación se castiga solo cuando la ley lo prevea, y si sigue la perpetración se castiga como inducción.'}},
{n:68, q:'Las personas criminalmente responsables de los delitos se encuentran reguladas:', o:{a:'En el Título II, del Libro I, artículos 27 a 31 quinquies, del Código Penal.',b:'En el Título I, del Libro I, artículos 27 a 31 ter, del Código Penal.',c:'En el Título I, del Libro I, artículos 27 a 31 bis, del Código Penal.',d:'En el Título III, del Libro I, artículos 27 a 31 quater, del Código Penal.'}, correct:'a', why:{a:'Las personas criminalmente responsables están reguladas en el Título II del Libro I, arts. 27 a 31 quinquies del CP.'}},
{n:69, q:'Según el art.27 del Código Penal, son responsables criminalmente de los delitos:', o:{a:'Todos los que participen en la ejecución del hecho delictivo.',b:'Los autores y los cómplices.',c:'Los autores y los encubridores.',d:'Los autores, cómplices y encubridores.'}, correct:'b', why:{b:'El art.27 CP establece que son responsables criminalmente los autores y los cómplices.'}},
{n:70, q:'De conformidad con lo dispuesto en el artículo 28 del Código Penal, son autores:', o:{a:'Quienes realizan el hecho delictivo por sí solos.',b:'Quienes realizan el hecho delictivo conjuntamente con otros.',c:'Quienes realizan el hecho delictivo por medio de otro del que se sirven como instrumento.',d:'Todos los descritos en las respuestas anteriores.'}, correct:'d', why:{d:'El art.28 CP define como autores a los que realizan el hecho por sí solos, conjuntamente o por medio de otro como instrumento.'}},
{n:71, q:'De conformidad con lo dispuesto en el artículo 28 del Código Penal, son autores:', o:{a:'Los que inducen directa o indirectamente a otro u otros a ejecutar el hecho delictivo.',b:'Los que cooperan en la ejecución del hecho delictivo con un acto sin el cual no se habría efectuado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.28 CP también considera autores a los inductores y a los cooperadores necesarios.'}},
{n:72, q:'Roberto quiere acabar con la vida de su vecino Javier con el que mantiene una larga enemistad. Para ello convence a su hijo de 5 años para que empuje desde el balcón una maceta al paso de Javier, lo cual se produce, causando a éste último graves lesiones. Teniendo en cuenta lo anterior, indique la respuesta correcta:', o:{a:'Roberto no es responsable de ningún delito porque la maceta ha sido arrojada por su hijo menor de edad.',b:'Roberto es autor de un delito como autor por inducción.',c:'Roberto es autor de un delito como cooperador necesario.',d:'Roberto es autor de un delito al utilizar a su hijo como instrumento.'}, correct:'d', why:{d:'Roberto utiliza a su hijo menor (sin capacidad de culpabilidad) como instrumento para cometer el delito, siendo autor mediato.'}},
{n:73, q:'Los que inducen a otro u otros a ejecutar un hecho delictivo, son considerados por el Código Penal:', o:{a:'Encubridores.',b:'Autores.',c:'Cómplices.',d:'Cooperadores necesarios.'}, correct:'b', why:{b:'Los inductores son considerados autores a efectos penales según el art.28 CP.'}},
{n:74, q:'Los que cooperan en la ejecución de un hecho delictivo, con un acto sin el cual éste no se hubiere efectuado, son considerados por el Código Penal:', o:{a:'Cómplices.',b:'Autores.',c:'Encubridores.',d:'Cómplices o encubridores, dependiendo del grado de inducción que el sujeto haya tenido en el hecho.'}, correct:'b', why:{b:'Los cooperadores necesarios son considerados autores a efectos penales (art.28 CP).'}},
{n:75, q:'Los que, sin ser autores, cooperan en la ejecución del hecho delictivo con actos anteriores o simultáneos:', o:{a:'Son cómplices.',b:'Son autores por cooperación necesaria.',c:'Son cómplices, si los actos son de cooperación necesaria.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Los que cooperan con actos anteriores o simultáneos sin ser necesarios son cómplices (art.29 CP).'}},
{n:76, q:'El art.63 del Código Penal dispone que a los cómplices de un delito consumado o intentado se les impondrá:', o:{a:'La pena inferior en uno o dos grados a la fijada por la ley para los autores del mismo.',b:'La pena inferior en grado a la fijada por la ley para los autores del mismo.',c:'La pena fijada por la ley para los autores del mismo, en su grado inferior.',d:'La pena fijada por la ley para los autores del mismo, en su grado medio.'}, correct:'b', why:{b:'El art.63 CP establece que a los cómplices se les impondrá la pena inferior en grado a la fijada para los autores.'}},
{n:77, q:'Respecto a la pena a imponer a los cómplices de un delito consumado o intentado, el art.64 del Código Penal determina que, la regla establecida para tal fin en el art.63 de dicho código, no será de aplicación:', o:{a:'Cuando la complicidad se halle especialmente penada por la Ley.',b:'Cuando la pena a imponer a los autores del mismo sea por comisión de un delito leve.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.64 CP establece que la regla del art.63 no aplica cuando la complicidad está especialmente penada por la Ley.'}},
{n:78, q:'De conformidad con el artículo 30 del Código Penal, en los delitos que se cometan utilizando medios o soportes de difusión mecánicos...', o:{a:'Responderán criminalmente los cómplices.',b:'No responderán criminalmente quienes los hubieren favorecido personal o realmente.',c:'Solo responderán los directores de la publicación o programa en que se difunda el delito.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art.30 CP establece un orden escalonado de responsabilidad para los delitos cometidos mediante medios de difusión, diferente a las opciones planteadas.'}},
{n:79, q:'El art.30 del Código Penal establece un orden según el cual los autores de los delitos que se cometan utilizando medios o soportes de difusión mecánicos responderán:', o:{a:'De forma escalonada, excluyente y subsidiaria.',b:'Según el grado de participación en el hecho delictivo.',c:'Atendiendo al grado de responsabilidad penal de sus actos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art.30 CP establece un sistema escalonado, excluyente y subsidiario de responsabilidad en delitos cometidos con medios de difusión.'}},
{n:80, q:'Indique cual de las siguientes respuestas no se corresponde con el orden de responsabilidad establecido en el artículo 30 del Código Penal, para los delitos que se cometan utilizando medios o soportes de difusión mecánicos:', o:{a:'1.º Responderán los directores de grabación, reproducción e impresión.',b:'2.º Responderán los directores de la publicación o programa en que se difunda.',c:'3.º Responderán los directores de la empresa editora, emisora o difusora.',d:'4.º Responderán los directores de grabación, reproducción o impresora'}, correct:'a', why:{a:'Según el art.30 CP, el primer responsable es quien haya redactado el texto o producido el signo, no el director de grabación.'}},
{n:81, q:'Indique cual de las siguientes respuestas se corresponde con el orden de responsabilidad establecido en el artículo 30 del Código Penal, para los delitos que se cometan utilizando medios o soportes de difusión mecánicos:', o:{a:'En primer lugar responden los que hayan redactado el texto o producido el signo de que se trate, y quienes les hayan inducido a realizarlo.',b:'En segundo lugar responden los directores de la empresa editora, emisora o difusora.',c:'En tercer lugar responden los directores de la empresa grabadora, reproductora o impresora.',d:'En cuarto lugar responden los directores de grabación, reproducción e impresión.'}, correct:'a', why:{a:'Según el art.30 CP, en primer lugar responden los autores del texto o del signo y quienes les hayan inducido.'}},
{n:82, q:'Cuando por cualquier motivo distinto de la extinción de la responsabilidad penal, incluso la declaración de rebeldía o la residencia fuera de España, no pueda perseguirse a ninguna de las personas comprendidas en el orden de responsabilidad establecido en el art.30 del Código Penal, para los delitos que se cometan utilizando medios o soportes de difusión mecánicos...', o:{a:'Se dirigirá el procedimiento contra las mencionadas en el número inmediatamente anterior.',b:'Se dirigirá el procedimiento contra las mencionadas en el número inmediatamente posterior.',c:'Se dirigirá el procedimiento contra las que corresponda conforme establece el art.31 bis) del Código Penal.',d:'Se dirigirá el procedimiento contra las que corresponda conforme establece el art.31 ter) del Código Penal.'}, correct:'b', why:{b:'Cuando no pueda perseguirse a uno de los responsables del art.30 CP, se dirige el procedimiento contra el del número siguiente (posterior).'}},
{n:83, q:'De acuerdo con lo previsto en el artículo 31 bis del Código Penal, las personas jurídicas son penalmente responsables de los delitos:', o:{a:'Cometidos en nombre o por cuenta de las mismas, y en su beneficio directo o indirecto, por sus representantes legales, o por aquellos que estén autorizados para tomar decisiones en nombre de la persona jurídica, u ostenten facultades de organización y control dentro de la misma.',b:'Cometidos en el ejercicio de actividades sociales y por cuenta y en beneficio directo o indirecto de las mismas, por quienes estando sometidos a la autoridad de las personas físicas que ostentan la representación legal, han podido realizar los hechos por haberse incumplido gravemente los deberes de supervisión, vigilancia y control de su actividad, atendidas las concretas circunstancias del caso.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.31 bis CP establece la responsabilidad penal de las personas jurídicas en ambos supuestos descritos.'}},
{n:84, q:'De acuerdo con lo previsto en el artículo 31 bis del Código Penal, para que las personas jurídicas queden exentas de responsabilidad penal por los hechos delictivos cometidos en nombre o por cuenta de las mismas, y en su beneficio directo o indirecto, por sus representantes legales, se requiere:', o:{a:'Haber adoptado y ejecutado con eficacia, antes de la comisión del delito, modelos de organización y gestión que incluyan medidas para prevenir o reducir delitos de la misma naturaleza.',b:'Supervisión del funcionamiento y cumplimiento del modelo implantado por un órgano de la persona jurídica con poderes autónomos.',c:'Que los autores individuales hayan cometido el delito eludiendo fraudulentamente los modelos de organización y prevención, y no se ha producido una omisión o ejercicio insuficiente de las funciones de supervisión, vigilancia y control de la persona jurídica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.31 bis CP exige todos esos requisitos para eximir de responsabilidad a la persona jurídica.'}},
{n:85, q:'A efectos de eximir de responsabilidad penal, el art.31.3 bis) del Código Penal establece que son personas jurídicas de pequeñas dimensiones:', o:{a:'Aquéllas que, según la legislación aplicable, estén autorizadas a presentar cuenta de pérdidas y ganancias abreviada.',b:'Aquéllas que, según la legislación vigente, estén autorizadas a presentar cuentas sobre la contabilidad de la organización de que se trate.',c:'Aquéllas que, según la legislación aplicable, estén autorizadas a gestionar la contabilidad de la organización de que se trate.',d:'Aquéllas que, según la legislación vigente, estén autorizadas a gestionar la contabilidad de la organización de que se trate.'}, correct:'a', why:{a:'El art.31 bis 3 CP considera personas jurídicas de pequeñas dimensiones las autorizadas a presentar cuenta de pérdidas y ganancias abreviada.'}},
{n:86, q:'De acuerdo con lo previsto en el artículo 31 bis del Código Penal, para que las personas jurídicas queden exentas de responsabilidad penal por los hechos delictivos cometidos en el ejercicio de actividades sociales por las personas sometidas a la autoridad de sus representantes legales, se requiere:', o:{a:'La denuncia inmediata y directa de los hechos ante la autoridad judicial, antes del inicio del proceso penal.',b:'La reparación del daño causado a las administraciones públicas o a terceros de buena fe, antes de la apertura del juicio oral.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Los requisitos para eximir a la persona jurídica en este supuesto son distintos: haber adoptado modelos de prevención, supervisión eficaz y que el delito fue cometido eludiendo fraudulentamente dichos modelos.'}},
{n:87, q:'Según lo establecido en el art.31 bis), apartado 1.b), del Código Penal, relativo a los delitos cometidos, en el ejercicio de actividades sociales y por cuenta y en beneficio directo o indirecto de las mismas, la persona jurídica quedará exenta de responsabilidad:', o:{a:'Si, antes de la comisión del delito, ha adoptado y ejecutado eficazmente un modelo de organización y gestión que resulte adecuado para prevenir delitos de la naturaleza del que fue cometido o para reducir de forma significativa el riesgo de su comisión.',b:'Cuando los autores individuales hayan cometido el delito eludiendo fraudulentamente los modelos de organización y prevención.',c:'Cuando no se ha producido una omisión o ejercicio insuficiente de las funciones de supervisión, vigilancia y control de la persona jurídica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La exención de la persona jurídica requiere todos esos requisitos conjuntamente según el art.31 bis CP.'}},
{n:88, q:'Según el art.31 quater del Código Penal, es circunstancia atenuante de la responsabilidad penal de las personas jurídicas:', o:{a:'Haber procedido, antes de conocer que el procedimiento judicial se dirige contra ella, a confesar la infracción a las autoridades.',b:'Haber colaborado en la investigación del hecho aportando pruebas, en cualquier momento del proceso, que fueran nuevas y decisivas para esclarecer las responsabilidades penales dimanantes de los hechos.',c:'Haber procedido en cualquier momento del procedimiento y con anterioridad al juicio oral a reparar o disminuir el daño causado por el delito.',d:'Son todas las descritas en las respuestas anteriores.'}, correct:'d', why:{d:'El art.31 quater CP establece como atenuantes de la responsabilidad penal de las personas jurídicas todas las circunstancias mencionadas.'}},
{n:89, q:'Según el art.31 quater del Código Penal, es circunstancia atenuante de la responsabilidad penal de las personas jurídicas:', o:{a:'La denuncia inmediata y directa de los hechos ante la autoridad judicial, antes del inicio del proceso penal.',b:'Haber establecido, antes del comienzo del juicio oral, medidas eficaces para prevenir y descubrir los delitos que en el futuro pudieran cometerse con los medios o bajo la cobertura de la persona jurídica.',c:'La reparación del daño causado a las administraciones públicas o a terceros de buena fe, antes de la apertura del juicio oral.',d:'Son todas las descritas en las respuestas anteriores.'}, correct:'d', why:{d:'El art.31 quater CP incluye como atenuantes todas las circunstancias mencionadas para las personas jurídicas.'}},
{n:90, q:'Según dispone el art.31 quinquies del Código Penal, las disposiciones relativas a la responsabilidad penal de las personas jurídicas:', o:{a:'Son aplicables a las administraciones públicas territoriales e institucionales, a los Organismos Reguladores, ni a las Agencias y Entidades públicas Empresariales.',b:'No serán aplicables a las organizaciones internacionales de derecho público, ni a aquellas otras que ejerzan potestades públicas de soberanía o administrativas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.31 quinquies CP establece que las disposiciones sobre responsabilidad penal de personas jurídicas no se aplican a organizaciones internacionales de derecho público ni a las que ejerzan potestades públicas de soberanía.'}},
{n:91, q:'Según dispone el art.31 quinquies del Código Penal, las disposiciones relativas a la responsabilidad penal de las personas jurídicas:', o:{a:'No serán aplicables al Estado, a las Administraciones públicas territoriales e institucionales, a los Organismos Reguladores, ni a las Agencias y Entidades públicas Empresariales.',b:'No serán aplicables a las organizaciones internacionales de derecho público, ni a aquellas otras que ejerzan potestades públicas de soberanía o administrativas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.31 quinquies CP excluye tanto al Estado y administraciones públicas como a las organizaciones internacionales de derecho público de la responsabilidad penal de personas jurídicas.'}},
{n:92, q:'Las circunstancias modificativas de la responsabilidad penal están contempladas en el Código Penal dentro de su:', o:{a:'Título Preliminar.',b:'Libro I.',c:'Libro II.',d:'Libro III.'}, correct:'b', why:{b:'Las circunstancias modificativas de la responsabilidad penal están reguladas en el Libro I del CP.'}},
{n:93, q:'El Código Penal regula las causas que eximen de la responsabilidad criminal:', o:{a:'En el Capítulo II, del Título I, del Libro I, artículos 19 y 20.',b:'En el Capítulo II, del Título I, del Libro I, artículos 18 a 20.',c:'En el Capítulo II, del Título II, del Libro I, artículos 18 y 20.',d:'En el Capítulo II, del Título II, del Libro I, artículos 19 y 20.'}, correct:'a', why:{a:'Las causas de exención de responsabilidad criminal están en el Capítulo II, Título I, Libro I, arts. 19 y 20 CP.'}},
{n:94, q:'Según lo establecido en el art.19 del Código Penal, cuando un menor de 18 años cometa un hecho delictivo:', o:{a:'No será responsable criminalmente con arreglo al Código Penal.',b:'Podrá ser responsable con arreglo a la ley que regula la responsabilidad penal del menor (LO 5/2000).',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.19 CP establece que los menores de 18 años no son responsables conforme al CP, pero sí pueden serlo según la LO 5/2000 de responsabilidad penal del menor.'}},
{n:95, q:'Está exento de responsabilidad criminal el que, al tiempo de cometer la infracción penal, a causa de cualquier anomalía o alteración psíquica...', o:{a:'No pueda comprender la ilicitud del hecho o actuar conforme a esa comprensión.',b:'Obre por causas o estímulos tan poderosos que le hayan provocado arrebato, obcecación u otro estado pasional de semejante entidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.20.1 CP exime de responsabilidad al que por anomalía o alteración psíquica no pueda comprender la ilicitud o actuar conforme a esa comprensión.'}},
{n:96, q:'El trastorno mental transitorio...', o:{a:'Exime de responsabilidad criminal en todo caso.',b:'No exime de responsabilidad criminal cuando hubiese sido buscado por el sujeto con el propósito de cometer el delito.',c:'No exime de responsabilidad criminal cuando el sujeto activo hubiera previsto o debido prever la comisión del delito.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'El trastorno mental transitorio no exime cuando fue buscado por el sujeto o cuando debía haberlo previsto (art.20.1 in fine CP).'}},
{n:97, q:'Es causa de exención de la responsabilidad criminal:', o:{a:'Obrar impulsado por miedo insuperable.',b:'El trastorno mental transitorio, salvo que hubiese sido provocado por el sujeto con el propósito de cometer el delito, o se hubiera previsto o debido prever su comisión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Tanto el miedo insuperable (art.20.6 CP) como el trastorno mental transitorio (art.20.1 CP) son causas de exención de responsabilidad criminal.'}},
{n:98, q:'El consumo de bebidas alcohólicas, drogas tóxicas, estupefacientes y sustancias psicotrópicas exime de responsabilidad criminal...', o:{a:'Siempre que el culpable haya actuado a causa de su grave adicción a estas sustancias, y que su adicción no haya sido buscada con el propósito de cometer el delito, o no se hubiese previsto o debido prever su comisión.',b:'Siempre que el sujeto activo, a la hora de cometer el delito, se halle en estado de intoxicación plena y que ésta no haya sido buscada con el propósito de cometer el delito, o no se hubiese previsto o debido prever su comisión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.20.2 CP exime de responsabilidad al que actúa en estado de intoxicación plena por consumo de alcohol u otras sustancias, siempre que no haya sido buscada para delinquir.'}},
{n:99, q:'El que al tiempo de cometer la infracción criminal se halle en estado de intoxicación plena por el consumo de bebidas alcohólicas, drogas tóxicas, estupefacientes, sustancias psicotrópicas y otras que produzcan efectos análogos:', o:{a:'Está exento de responsabilidad criminal, siempre que este estado no haya sido buscado con el propósito de cometer el delito, o no se hubiese previsto o debido prever su comisión.',b:'Atenúa su responsabilidad criminal, siempre que este estado no haya sido buscado con el propósito de cometer el delito, o no se hubiese previsto o debido prever su comisión.',c:'Agrava su responsabilidad criminal siempre que este estado haya sido buscado con el propósito de cometer el delito, o no se hubiese previsto o debido prever su comisión.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La intoxicación plena que no fue buscada para delinquir exime de responsabilidad criminal (art.20.2 CP).'}},
{n:100, q:'El que al tiempo de cometer la infracción criminal se halle bajo la influencia de un síndrome de abstinencia, a causa de su dependencia a las drogas tóxicas, estupefacientes o sustancias psicotrópicas, que le impida conocer la ilicitud del hecho o actuar conforme a esa comprensión:', o:{a:'Atenúa su responsabilidad criminal.',b:'Está exento de responsabilidad criminal.',c:'Atenúa su responsabilidad criminal, siempre que dicho estado no haya sido buscado con el propósito de delinquir, o no se hubiese previsto o podido prever su comisión.',d:'Está exento de responsabilidad criminal, siempre que dicho estado no haya sido buscado con el propósito de delinquir, o no se haya previsto o podido prever su comisión.'}, correct:'d', why:{d:'El síndrome de abstinencia que impide comprender la ilicitud exime de responsabilidad si no fue buscado para delinquir (art.20.2 CP).'}},
{n:101, q:'Para que las alteraciones en la percepción constituyan causa de exención de la responsabilidad criminal, se exige...', o:{a:'Que el sujeto se halle bajo un estado de trastorno mental transitorio.',b:'Que dichas alteraciones se padezcan desde el nacimiento o desde la infancia.',c:'Que a consecuencia de dichas alteraciones, el sujeto tenga gravemente alterada la conciencia de la realidad.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'El art.20.3 CP exige que las alteraciones en la percepción se padezcan desde el nacimiento o infancia y que tengan gravemente alterada la conciencia de la realidad.'}},
{n:102, q:'Para que constituya causa de exención de la responsabilidad criminal, el miedo...', o:{a:'No debe ser buscado con el propósito de cometer la infracción penal.',b:'Debe alterar gravemente la conciencia de la realidad.',c:'Debe ser insuperable.',d:'Debe ser de tal intensidad que impida comprender la ilicitud del hecho, o actuar conforme a esa comprensión.'}, correct:'c', why:{c:'Para que el miedo exima de responsabilidad debe ser insuperable (art.20.6 CP).'}},
{n:103, q:'El Código Penal exime de responsabilidad criminal al que:', o:{a:'Obre en defensa de la persona o derechos propios o ajenos, siempre que concurran determinados requisitos regulados en el art.20 de dicho código.',b:'Cometa el delito a causa de su grave adicción al consumo de bebidas alcohólicas, drogas tóxicas, estupefacientes, sustancias psicotrópicas u otras que produzcan efectos análogos.',c:'Obre por causas o estímulos tan poderosos que le hayan provocado arrebato, obcecación u otro estado pasional de semejante entidad.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'La legítima defensa (art.20.4 CP) exime de responsabilidad al que obra en defensa propia o ajena cumpliendo sus requisitos.'}},
{n:104, q:'Es requisito necesario para que concurra la eximente de legítima defensa:', o:{a:'Que el necesitado no tenga, por su oficio o cargo, obligación de sacrificarse.',b:'Agresión ilegítima.',c:'Que el atacante tenga alterada gravemente la conciencia de la realidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La agresión ilegítima es el primer y principal requisito de la legítima defensa (art.20.4 CP).'}},
{n:105, q:'Con respecto a la eximente de legítima defensa, en caso de defensa de los bienes, se reputará agresión ilegítima el ataque a los mismos:', o:{a:'Que constituya delito y los ponga en peligro de deterioro o pérdida inminente.',b:'Que constituya delito y los ponga en peligro de grave deterioro o pérdida inminente.',c:'Que los ponga en situación de grave riesgo de pérdida o destrucción inminentes.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'En defensa de bienes, se considera agresión ilegítima el ataque que constituya delito y los ponga en peligro de grave deterioro o pérdida inminente.'}},
{n:106, q:'Con respecto a la eximente de legítima defensa, en caso de defensa de la morada o sus dependencias, se reputará agresión ilegítima:', o:{a:'El intento de acceder a ellas por vía distinta a la habitual.',b:'El intento de penetrar en ellas por la fuerza.',c:'La entrada indebida en aquella o éstas.',d:'Las respuestas a y b son correctas.'}, correct:'c', why:{c:'En defensa de la morada, se considera agresión ilegítima la entrada indebida en la misma o sus dependencias (art.20.4 CP).'}},
{n:107, q:'Está exento de responsabilidad criminal:', o:{a:'El que obra en cumplimiento de un deber.',b:'El que obra en el ejercicio legítimo de un derecho.',c:'El que obre en el ejercicio legítimo de un oficio o cargo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.20.7 CP exime de responsabilidad al que obra en cumplimiento de un deber o en el ejercicio legítimo de un derecho, oficio o cargo.'}},
{n:108, q:'Con relación a la eximente de estado de necesidad, indique la respuesta correcta:', o:{a:'La lesión del bien jurídico de otra persona, o la infracción de un determinado deber debe tener como fundamento evitar un mal propio o ajeno.',b:'El mal causado no debe ser mayor que el que se trata de evitar.',c:'La situación de necesidad no tiene que haber sido provocada intencionadamente por el sujeto.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El estado de necesidad (art.20.5 CP) requiere todos esos elementos para eximir de responsabilidad.'}},
{n:109, q:'Para que concurra la eximente de estado de necesidad, es preciso:', o:{a:'Que el necesitado no tenga por su oficio o cargo, obligación de sacrificarse.',b:'Que exista necesidad racional del medio empleado para impedir o repeler la acción.',c:'Que exista falta de provocación suficiente por parte del sujeto activo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Uno de los requisitos del estado de necesidad es que el necesitado no tenga por su oficio o cargo obligación de sacrificarse (art.20.5.3ª CP).'}},
{n:110, q:'No es un requisito exigido para apreciar la eximente de estado de necesidad:', o:{a:'Padecer alteraciones en la percepción desde el nacimiento o infancia, que alteren gravemente la conciencia de la realidad.',b:'Que el mal causado no sea mayor que el que se trata de evitar.',c:'Que la situación de necesidad no haya sido provocada intencionadamente por el sujeto.',d:'Que el necesitado no tenga por su oficio o cargo, obligación de sacrificarse.'}, correct:'a', why:{a:'Las alteraciones en la percepción desde el nacimiento son requisito de la eximente del art.20.3 CP, no del estado de necesidad.'}},
{n:111, q:'Con respecto a las causas que eximen de la responsabilidad criminal, en las que no concurren todos los requisitos necesarios para ello, el Código Penal dispone:', o:{a:'Que pueden ser consideradas circunstancias atenuantes.',b:'Que pueden eximir de responsabilidad criminal cuando sean muy cualificadas.',c:'Que permitirán la imposición de la pena prevista para cada supuesto en su mitad inferior.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Las eximentes incompletas pueden ser atenuantes, eximir cuando son muy cualificadas, o permitir la pena en su mitad inferior, según el art.21.1ª y 68 CP.'}},
{n:112, q:'El Capitulo III del Título I, del Libro Primero del Código Penal, regula:', o:{a:'Las circunstancias que eximen de responsabilidad criminal.',b:'Las circunstancias que atenúan la responsabilidad criminal.',c:'Las circunstancias que agravan la responsabilidad criminal.',d:'Las circunstancias mixtas de parentesco en la responsabilidad criminal.'}, correct:'b', why:{b:'El Capítulo III del Título I del Libro I regula las circunstancias atenuantes de la responsabilidad criminal.'}},
{n:113, q:'En nuestro Código Penal, el hecho de actuar el culpable a causa de su grave adicción al alcohol, drogas tóxicas, estupefacientes o sustancias psicotrópicas:', o:{a:'Constituye circunstancia agravante.',b:'Constituye circunstancia atenuante.',c:'Constituye circunstancia mixta.',d:'Constituye circunstancia eximente.'}, correct:'b', why:{b:'La grave adicción a sustancias es una circunstancia atenuante de la responsabilidad criminal (art.21.2ª CP).'}},
{n:114, q:'El hecho de obrar por causas o estímulos poderosos solo constituye atenuante de la responsabilidad criminal cuando:', o:{a:'Haya producido arrebato, trastorno mental o alteración psíquica.',b:'Haya producido arrebato, obcecación u otro estado pasional de semejante entidad.',c:'Haya provocado en el sujeto una grave alteración de su conciencia de la realidad.',d:'Ninguna de las respuestas es correcta.'}, correct:'b', why:{b:'El arrebato u obcecación es atenuante cuando se actúa por causas o estímulos poderosos (art.21.3ª CP).'}},
{n:115, q:'La confesión a las autoridades, por parte del culpable de una infracción penal...', o:{a:'Solo atenúa la responsabilidad criminal cuando se lleve a cabo antes de la celebración del acto del juicio oral.',b:'Solo exime de responsabilidad criminal cuando se lleve a cabo antes de la celebración del acto del juicio oral.',c:'Solo atenúa la responsabilidad criminal cuando se lleve a cabo antes de conocer que el procedimiento judicial se dirige contra él.',d:'Solo exime de responsabilidad criminal cuando se lleve a cabo antes de conocer que el procedimiento judicial se dirige contra él.'}, correct:'c', why:{c:'La confesión atenúa solo si se hace antes de conocer que el procedimiento judicial se dirige contra el culpable (art.21.4ª CP).'}},
{n:116, q:'Para que pueda ser considerada atenuante la reparación del daño causado a la víctima por parte del culpable de la infracción penal, dicha reparación debe tener lugar...', o:{a:'En cualquier momento del procedimiento, anterior al trámite de audiencia.',b:'En cualquier momento del procedimiento anterior a la sentencia.',c:'Antes de conocer que el procedimiento se dirige contra él.',d:'En cualquier momento del procedimiento anterior al acto de juicio oral.'}, correct:'d', why:{d:'La reparación del daño como atenuante debe producirse en cualquier momento del procedimiento y con anterioridad al juicio oral (art.21.5ª CP).'}},
{n:117, q:'Haber procedido el culpable, antes de conocer que el procedimiento judicial se dirige contra él, a confesar la infracción a las autoridades, es circunstancia:', o:{a:'Que atenúa la responsabilidad criminal.',b:'Que atenúa la responsabilidad civil.',c:'Que exime de responsabilidad penal y civil.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'La confesión antes de conocer que el procedimiento se dirige contra uno es circunstancia atenuante (art.21.4ª CP).'}},
{n:118, q:'Para que se pueda considerar circunstancia atenuante de la responsabilidad criminal la dilación extraordinaria e indebida en la tramitación de un procedimiento penal, es necesario que:', o:{a:'Dicha dilación no sea atribuible al propio inculpado.',b:'Dicha dilación no guarde proporción con la complejidad de la causa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Para que las dilaciones indebidas sean atenuante se requiere que no sean atribuibles al inculpado y que no guarden proporción con la complejidad (art.21.6ª CP).'}},
{n:119, q:'El Código Penal regula las circunstancias que agravan la responsabilidad criminal...', o:{a:'En el art.21 del Capítulo VI, del Título I, del Libro Primero.',b:'En el art.22 del Capítulo IV, del Título I, del Libro Primero.',c:'En los artículos 21 y 22 del Capítulo VI, del Título I, del Libro Primero.',d:'En los artículos 21 y 22 del Capítulo IV, del Título II, del Libro Primero.'}, correct:'b', why:{b:'Las circunstancias agravantes están reguladas en el art.22 del Capítulo IV, Título I, Libro I del CP.'}},
{n:120, q:'Cuando el culpable comete cualquiera de los delitos contra las personas empleando en la ejecución medios, modos o formas que tiendan directa y especialmente a asegurarla, sin el riesgo que para su persona pudiera proceder de la defensa que realice el ofendido:', o:{a:'Concurre la agravante de premeditación.',b:'Concurre la agravante de alevosía.',c:'Concurre la agravante de abuso de superioridad.',d:'Concurre la agravante de ensañamiento.'}, correct:'b', why:{b:'La alevosía concurre cuando se emplean medios que aseguran el delito sin riesgo para el culpable (art.22.1ª CP).'}},
{n:121, q:'Ejecutar el hecho con alevosía:', o:{a:'Atenúa la responsabilidad criminal.',b:'Agrava la responsabilidad civil.',c:'Atenúa o agrava la responsabilidad criminal dependiendo de las circunstancias del hecho.',d:'Agrava la responsabilidad criminal.'}, correct:'d', why:{d:'La alevosía es circunstancia agravante de la responsabilidad criminal (art.22.1ª CP).'}},
{n:122, q:'La alevosía sólo puede concurrir:', o:{a:'En los delitos contra las personas.',b:'En los delitos contra el patrimonio.',c:'En los delitos imprudentes.',d:'En los delitos contra la vida.'}, correct:'a', why:{a:'La alevosía solo puede concurrir en los delitos contra las personas (art.22.1ª CP).'}},
{n:123, q:'Ejecutar el hecho delictivo con abuso de superioridad, constituye circunstancia agravante cuando...', o:{a:'Debilite la defensa del ofendido.',b:'Favorezca el abuso de confianza.',c:'Aumente el sufrimiento de la víctima.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El abuso de superioridad como agravante requiere que debilite la defensa del ofendido (art.22.2ª CP).'}},
{n:124, q:'Aprovecharse de las circunstancias de lugar y tiempo al ejecutar un hecho delictivo, constituye circunstancia agravante, siempre que...', o:{a:'Se debilite la defensa del ofendido.',b:'Se realice por razones de género.',c:'Provoque padecimientos innecesarios a la víctima.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Aprovecharse de circunstancias de lugar y tiempo es agravante cuando debilita la defensa del ofendido (art.22.2ª CP).'}},
{n:125, q:'Ejecutar un hecho delictivo aprovechando el auxilio de otras personas, constituye circunstancia agravante de la responsabilidad criminal, cuando...', o:{a:'Se debilite la defensa del ofendido.',b:'Se facilite la impunidad del delincuente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El auxilio de otras personas es agravante cuando debilita la defensa del ofendido (art.22.2ª CP).'}},
{n:126, q:'Es circunstancia que agrava la responsabilidad criminal:', o:{a:'Ejecutar el hecho mediante precio.',b:'Ejecutar el hecho por venganza u otra circunstancia análoga.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Ejecutar el hecho mediante precio, recompensa o promesa es circunstancia agravante (art.22.3ª CP).'}},
{n:127, q:'Es circunstancia que agrava la responsabilidad criminal:', o:{a:'Ejecutar el hecho mediante promesa.',b:'Ejecutar el hecho mediante recompensa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Ejecutar el hecho mediante precio, recompensa o promesa agrava la responsabilidad criminal (art.22.3ª CP).'}},
{n:128, q:'Es circunstancia que agrava la responsabilidad criminal:', o:{a:'Ejecutar el hecho utilizando medios de especial potencialidad lesiva.',b:'Cometer el delito por motivos racistas o antisemitas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Tanto los medios de especial potencialidad lesiva (art.22.4ª) como los motivos discriminatorios (art.22.4ª) son agravantes.'}},
{n:129, q:'Es circunstancia que agrava la responsabilidad criminal el hecho de cometer el delito por cualquier clase de discriminación referente a...', o:{a:'La edad de la víctima.',b:'La ideología de la víctima.',c:'La discapacidad de la víctima.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'La discriminación por ideología y por discapacidad son agravantes del art.22.4ª CP.'}},
{n:130, q:'Es circunstancia que agrava la responsabilidad criminal el hecho de cometer el delito por cualquier clase de discriminación referente a...', o:{a:'La religión de la víctima.',b:'La enfermedad que padezca la víctima.',c:'La nación a la que pertenezca la víctima.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La religión, la enfermedad y la nación de la víctima son motivos de discriminación que agravan la responsabilidad (art.22.4ª CP).'}},
{n:131, q:'Es circunstancia que agrava la responsabilidad criminal el hecho de cometer el delito por cualquier clase de discriminación referente a...', o:{a:'Razones de género.',b:'El sexo de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Tanto el género como el sexo de la víctima son motivos de discriminación que agravan (art.22.4ª CP).'}},
{n:132, q:'Cometer el delito por motivos racistas, antisemitas, antigitanos u otra clase de discriminación referente a la ideología, religión o creencias de la víctima, la etnia, raza o nación a la que pertenezca, su sexo, edad, orientación o identidad sexual o de género, razones de género, de aporofobia o de exclusión social, la enfermedad que padezca o su discapacidad...', o:{a:'Agrava la responsabilidad criminal, con independencia de que tales condiciones o circunstancias concurran efectivamente en la persona sobre la que recaiga la conducta.',b:'Agrava la responsabilidad criminal, siempre que tales condiciones o circunstancias concurran efectivamente en la persona sobre la que recaiga la conducta.',c:'Agrava la responsabilidad criminal, siempre y cuando tales condiciones o circunstancias concurran efectivamente en la persona sobre la que recaiga la conducta y esta sea menor de 16 años o necesitada de especial protección.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La agravante por discriminación se aplica con independencia de que las condiciones discriminatorias concurran efectivamente en la víctima (art.22.4ª CP).'}},
{n:133, q:'La agravante de ensañamiento consiste en:', o:{a:'Aumentar por acción o por omisión inhumanamente el sufrimiento de la víctima.',b:'Aumentar deliberadamente el sufrimiento de la víctima causando a ésta padecimientos necesarios o innecesarios para la ejecución del delito.',c:'Aumentar deliberada e inhumanamente el sufrimiento de la víctima, causando a ésta padecimientos innecesarios para la ejecución del delito.',d:'Aumentar ostensiblemente el sufrimiento de la víctima, causando a ésta padecimientos, sean necesarios o innecesarios para la ejecución del delito.'}, correct:'c', why:{c:'El ensañamiento consiste en aumentar deliberada e inhumanamente el sufrimiento de la víctima causando padecimientos innecesarios (art.22.5ª CP).'}},
{n:134, q:'Es circunstancia que agrava la responsabilidad criminal:', o:{a:'Obrar con abuso de confianza.',b:'Prevalerse del carácter público que tenga el culpable.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Tanto el abuso de confianza (art.22.6ª) como prevalerse del carácter público (art.22.7ª) son circunstancias agravantes.'}},
{n:135, q:'Hay reincidencia cuando, al delinquir, el culpable hubiese sido condenado:', o:{a:'Judicialmente por un delito comprendido en el mismo Título de este Código sea o no de la misma naturaleza.',b:'Ejecutoriamente por un delito comprendido en el mismo Capítulo de este Código, siempre que sea de la misma naturaleza.',c:'Ejecutoriamente por un delito comprendido en el mismo Título de este Código, siempre que sea de la misma naturaleza.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Hay reincidencia cuando el culpable fue condenado ejecutoriamente por delito del mismo Título del CP de la misma naturaleza (art.22.8ª CP).'}},
{n:136, q:'A efectos de apreciar la agravante de reincidencia:', o:{a:'No se computarán los antecedentes penales cancelados o que hubiesen debido serlo.',b:'No se computarán los antecedentes penales que correspondan a delitos imprudentes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Para apreciar la reincidencia no se computan los antecedentes cancelados ni los de delitos imprudentes (art.22.8ª CP).'}},
{n:137, q:'A efectos de apreciar la agravante de reincidencia:', o:{a:'Se tendrán en cuenta la proximidad temporal de los delitos cometidos y las posibilidades de reinserción social mostradas por el sujeto.',b:'No se computarán los antecedentes penales que correspondan a delitos leves.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son correctas.'}, correct:'c', why:{c:'Para la reincidencia se tienen en cuenta la proximidad temporal y se excluyen antecedentes de delitos leves.'}},
{n:138, q:'Las condenas firmes de jueces o tribunales impuestas en otros Estados de la Unión Europea..', o:{a:'Producirán los efectos de reincidencia.',b:'Producirán los efectos de reincidencia, siempre que los hechos objetos de condena penal sean igualmente punibles con arreglo al Derecho Español.',c:'Producirán los efectos de reincidencia, salvo que el antecedente penal haya sido cancelado o pudiera serlo con arreglo al Derecho Español.',d:'No producirán los efectos de la reincidencia.'}, correct:'b', why:{b:'Las condenas de la UE producen efectos de reincidencia cuando los hechos sean igualmente punibles según el Derecho español (art.22.8ª in fine CP).'}},
{n:139, q:'El Capítulo V, del Título I del Libro Primero del Código Penal, regula:', o:{a:'La circunstancia mixta de parentesco en la responsabilidad criminal.',b:'Las circunstancias agravantes de la responsabilidad criminal.',c:'Las circunstancias que eximen de responsabilidad criminal.',d:'Las circunstancias que atenúan la responsabilidad criminal.'}, correct:'a', why:{a:'El Capítulo V del Título I del Libro I regula la circunstancia mixta de parentesco.'}},
{n:140, q:'Ser el agraviado cónyuge o persona ligada por análoga relación de afectividad es circunstancia:', o:{a:'Que agrava la responsabilidad criminal.',b:'Que exime de responsabilidad criminal.',c:'Que atenúa la responsabilidad criminal.',d:'Que puede atenuar o agravar la responsabilidad criminal.'}, correct:'d', why:{d:'El parentesco es una circunstancia mixta que puede atenuar o agravar la responsabilidad según el delito (art.23 CP).'}},
{n:141, q:'Ser el agraviado ascendiente, descendiente o hermano del ofensor es circunstancia que:', o:{a:'Agrava la responsabilidad criminal.',b:'Atenúa la responsabilidad criminal.',c:'Puede atenuar o agravar la responsabilidad criminal.',d:'Exime de responsabilidad criminal.'}, correct:'c', why:{c:'El parentesco es circunstancia mixta que puede atenuar o agravar según la naturaleza del delito (art.23 CP).'}},
{n:142, q:'Respecto a las disposiciones comunes a las circunstancias modificativas de la responsabilidad criminal, la STS 587/2020 determina que:', o:{a:'En las circunstancias modificativas de la responsabilidad criminal la carga de la prueba corresponde a la parte que las alega, y deben estar tan acreditadas como el hecho delictivo mismo.',b:'Para las eximentes o atenuantes no rige la presunción de inocencia ni el principio "in dubio pro reo".',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La STS 587/2020 establece que las circunstancias modificativas deben acreditarse tan plenamente como el hecho delictivo.'}},
{n:143, q:'Las distintas clases de penas y su descripción están establecidas en el Título III, del Libro Primero del Código Penal que contiene:', o:{a:'3 Capítulos.',b:'4 Capítulos.',c:'5 Capítulos.',d:'6 Capítulos.'}, correct:'d', why:{d:'El Título III del Libro I del CP contiene 6 Capítulos: Cap.I (arts.32-34), Cap.II (arts.35-38), Cap.III (arts.39-49), Cap.IV (arts.50-53), Cap.V (arts.54-57) y Cap.VI (arts.58-67).'}},
{n:144, q:'El artículo 2 del Código Penal dispone que no será castigado ningún delito...', o:{a:'No resulte suficientemente probado en un procedimiento penal establecido al efecto.',b:'Con pena que no se halle prevista por ley anterior a su perpetración.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.2 CP establece el principio de legalidad de las penas: no se castigará con pena no prevista por ley anterior.'}},
{n:145, q:'El artículo 2 del Código Penal dispone que tendrán efecto retroactivo aquellas leyes penales que favorezcan al reo...', o:{a:'Siempre y cuando, al entrar en vigor, no hubiera recaído sentencia firme ni el sujeto estuviese cumpliendo condena.',b:'Aunque al entrar en vigor hubiera recaído sentencia firme, siempre que el sujeto no estuviese cumpliendo condena.',c:'Aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art.2.2 CP establece que las leyes penales más favorables se aplican retroactivamente aunque haya sentencia firme y el sujeto esté cumpliendo condena.'}},
{n:146, q:'Conforme a lo dispuesto en el artículo 3 del Código Penal, no podrá ejecutarse pena ni medida de seguridad...', o:{a:'Que no se haya impuesto en virtud de sentencia firme dictada por el Juez o Tribunal competente, de acuerdo con las leyes procesales.',b:'De otra forma que no sea la prescrita por la ley y los reglamentos que la desarrollan.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.3 CP exige sentencia firme de juez competente y que la ejecución sea conforme a la ley y reglamentos.'}},
{n:147, q:'A efectos de determinar la ley penal aplicable en el tiempo, los delitos se consideran cometidos:', o:{a:'En el momento en el que el sujeto ejecuta la acción.',b:'En el momento en que el sujeto omite el acto que estaba obligado a realizar.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El delito se comete tanto en el momento de la acción como en el de la omisión debida (teoría de la actividad).'}},
{n:148, q:'A los delitos que se hallen penados en leyes especiales, les son aplicables las disposiciones contenidas en:', o:{a:'El Título Preliminar del Código Penal.',b:'El Libro I del Código Penal.',c:'El Libro II del Código Penal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'Las disposiciones del Libro I del CP son aplicables supletoriamente a los delitos penados en leyes especiales.'}},
{n:149, q:'Según el art. 32 del Código Penal, las penas que pueden imponerse con arreglo a este Código, bien con carácter principal bien como accesorias, son:', o:{a:'Privativas de libertad o privativas de otros derechos.',b:'Privativas de libertad, privativas de otros derechos y multa.',c:'Privativas de libertad o de otros derechos, multa y trabajos en beneficio de la comunidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art.32 CP establece que las penas son privativas de libertad, privativas de otros derechos y multa.'}},
{n:150, q:'Según el art.33 del Código Penal, en función de su naturaleza y duración, las penas se clasifican en:', o:{a:'Graves, menos graves y leves.',b:'Principales y subsidiarias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.33 CP clasifica las penas en graves, menos graves y leves según su naturaleza y duración.'}},
{n:151, q:'La pena de localización permanente de un día a tres meses, se puede imponer:', o:{a:'Por delitos leves o menos graves.',b:'Solo por delitos leves.',c:'Por delitos leves, menos graves y graves.',d:'La localización permanente no es una pena, sino una medida de seguridad.'}, correct:'b', why:{b:'La localización permanente de 1 día a 3 meses es pena leve, aplicable solo por delitos leves (art.33.4.g CP).'}},
{n:152, q:'La privación de la patria potestad es una pena:', o:{a:'Grave.',b:'Menos Grave.',c:'Leve.',d:'La privación de la patria potestad no es una pena; es una medida de seguridad.'}, correct:'a', why:{a:'La privación de la patria potestad es una pena grave según el art.33.2 CP.'}},
{n:153, q:'La privación del derecho a la tenencia y porte de armas de tres meses a un año es una pena:', o:{a:'Leve',b:'Menos grave.',c:'Grave.',d:'No es una pena; es una medida de seguridad.'}, correct:'a', why:{a:'La privación del derecho a la tenencia y porte de armas de 3 meses a 1 año es pena leve (art.33.4 CP).'}},
{n:154, q:'La inhabilitación absoluta es una pena:', o:{a:'Leve',b:'Menos grave.',c:'Grave.',d:'Grave o menos grave, dependiendo de su duración.'}, correct:'c', why:{c:'La inhabilitación absoluta es siempre una pena grave (art.33.2.a CP).'}},
{n:155, q:'La suspensión de empleo o cargo público es una pena:', o:{a:'Leve',b:'Menos grave.',c:'Grave.',d:'Grave o menos grave, dependiendo de su duración.'}, correct:'d', why:{d:'La suspensión de empleo o cargo público puede ser grave (más de 5 años) o menos grave (hasta 5 años) según su duración.'}},
{n:156, q:'La privación del derecho a la tenencia y porte de armas de un año y un día a ocho años, es una pena:', o:{a:'Leve',b:'Menos grave.',c:'Grave.',d:'No es una pena; es una medida de seguridad.'}, correct:'b', why:{b:'La privación del derecho a la tenencia y porte de armas de 1 año y 1 día a 8 años es pena menos grave (art.33.3 CP).'}},
{n:157, q:'La suspensión de empleo o cargo público hasta cinco años, es una pena:', o:{a:'Grave.',b:'Menos Grave.',c:'Leve.',d:'La suspensión descrita no es una pena; es una medida de seguridad.'}, correct:'b', why:{b:'La suspensión de empleo o cargo público hasta 5 años es una pena menos grave (art.33.3 CP).'}},
{n:158, q:'La suspensión de empleo o cargo público por tiempo superior a cinco años, es una pena:', o:{a:'Grave.',b:'Menos Grave.',c:'Leve.',d:'La suspensión descrita no es una pena; es una medida de seguridad.'}, correct:'a', why:{a:'La suspensión de empleo o cargo público por más de 5 años es pena grave (art.33.2 CP).'}},
{n:159, q:'La inhabilitación especial para el ejercicio de profesión, oficio o comercio que tenga relación con los animales, y para la tenencia de animales, es una pena...', o:{a:'Leve o menos grave, dependiendo de su duración.',b:'Menos grave.',c:'Grave.',d:'Grave o menos grave, dependiendo de su duración.'}, correct:'d', why:{d:'La inhabilitación especial puede ser grave o menos grave dependiendo de su duración (art.33.2 y 33.3 CP).'}},
{n:160, q:'La inhabilitación especial para el ejercicio de profesión, oficio o comercio que tenga relación con los animales, y para la tenencia de animales, es una pena leve:', o:{a:'Cuando su duración es de 1 año y 1 día a 5 años.',b:'Cuando su duración es de 1 año y 1 día a 3 años.',c:'Cuando su duración es de 6 meses a 1 año.',d:'Cuando su duración es de 3 meses a 1 año.'}, correct:'d', why:{d:'La inhabilitación especial para tenencia de animales es leve cuando su duración es de 3 meses a 1 año (art.33.4 CP).'}},
{n:161, q:'La inhabilitación especial para el ejercicio de profesión, oficio o comercio que tenga relación con los animales, y para la tenencia de animales, es una pena menos grave:', o:{a:'Cuando su duración es de 1 año y 1 día a 5 años.',b:'Cuando su duración es de 1 año y 1 día a 3 años.',c:'Cuando su duración es de 6 meses a 1 año.',d:'Cuando su duración es de 3 meses a 1 año.'}, correct:'a', why:{a:'La inhabilitación especial para tenencia de animales es menos grave cuando dura de 1 año y 1 día a 5 años (art.33.3 CP).'}},
{n:162, q:'La privación del derecho a conducir vehículos a motor y ciclomotores es una pena...', o:{a:'Leve, grave o menos grave, dependiendo de su duración.',b:'Menos grave.',c:'Grave.',d:'Grave o menos grave, dependiendo de su duración'}, correct:'a', why:{a:'La privación del derecho a conducir puede ser leve, menos grave o grave según su duración (arts. 33.2, 33.3 y 33.4 CP).'}},
{n:163, q:'La privación del derecho a conducir vehículos a motor y ciclomotores es una pena leve:', o:{a:'Cuando su duración es de 1 año y 1 día a 5 años.',b:'Cuando su duración es de 1 año y 1 día a 3 años.',c:'Cuando su duración es de 6 meses a 1 año.',d:'Cuando su duración es de 3 meses a 1 año.'}, correct:'d', why:{d:'La privación del derecho a conducir es leve cuando dura de 3 meses a 1 año (art.33.4.f CP).'}},
{n:164, q:'La privación del derecho a conducir vehículos a motor y ciclomotores es una pena menos grave:', o:{a:'Cuando su duración es de 1 año y 1 día a 5 años.',b:'Cuando su duración es de 1 año y 1 día a 8 años.',c:'Cuando su duración es de 6 meses a 1 año.',d:'Cuando su duración es de 3 meses a 1 año.'}, correct:'b', why:{b:'La privación del derecho a conducir es menos grave cuando dura de 1 año y 1 día a 8 años (art.33.3 CP).'}},
{n:165, q:'La privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a ocho años, es una pena:', o:{a:'Grave.',b:'Menos grave.',c:'Leve.',d:'Grave o menos grave, dependiendo de la pena principal que se aplique.'}, correct:'a', why:{a:'La privación del derecho a conducir por más de 8 años es pena grave (art.33.2 CP).'}},
{n:166, q:'La privación del derecho a la tenencia y porte de armas por tiempo superior a ocho años, es una pena:', o:{a:'Grave.',b:'Menos grave.',c:'Leve.',d:'Grave o menos grave, dependiendo de la pena principal que se aplique.'}, correct:'a', why:{a:'La privación del derecho a la tenencia y porte de armas por más de 8 años es pena grave (art.33.2 CP).'}},
{n:167, q:'Según el art.33 del Código Penal, es una pena grave:', o:{a:'La prisión permanente revisable.',b:'Las inhabilitaciones especiales por tiempo superior a cinco años.',c:'La prisión superior a cinco años.',d:'Son graves las tres penas descritas en las respuestas anteriores.'}, correct:'d', why:{d:'La prisión permanente revisable, las inhabilitaciones especiales superiores a 5 años y la prisión superior a 5 años son todas penas graves (art.33.2 CP).'}},
{n:168, q:'Según el art.33 del Código Penal, es una pena grave:', o:{a:'Privación del derecho a residir en determinados lugares o acudir a ellos, por tiempo superior a cinco años.',b:'La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo superior a cinco años.',c:'La prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el Juez o Tribunal, por tiempo superior a cinco años.',d:'Son graves las tres penas descritas en las respuestas anteriores.'}, correct:'d', why:{d:'Las privaciones y prohibiciones de más de 5 años son penas graves según el art.33.2 CP.'}},
{n:169, q:'La pena de privación del derecho a la tenencia y porte de armas por un tiempo de un año y seis meses, tiene la consideración de pena:', o:{a:'Leve.',b:'Grave.',c:'Menos grave.',d:'Grave o menos grave, dependiendo de las circunstancias del hecho.'}, correct:'c', why:{c:'La privación del derecho a la tenencia y porte de armas de 1 año y 1 día a 8 años es pena menos grave.'}},
{n:170, q:'Los trabajos en beneficio de la comunidad constituyen una pena:', o:{a:'Leve, grave o menos grave, dependiendo de su duración.',b:'Leve o menos grave, dependiendo de su duración.',c:'Leve.',d:'Grave o menos grave, dependiendo de su duración'}, correct:'b', why:{b:'Los trabajos en beneficio de la comunidad pueden ser leves o menos graves según su duración (art.33.3 y 33.4 CP).'}},
{n:171, q:'Según el art.33 del Código Penal, la multa de hasta tres meses es una pena:', o:{a:'Leve.',b:'Que puede ser sustituida a requerimiento del condenado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La multa de hasta 3 meses es una pena leve según el art.33.4 CP.'}},
{n:172, q:'Los trabajos en beneficio de la comunidad de 31 días a un año, constituyen una pena:', o:{a:'Grave.',b:'Menos Grave.',c:'Leve.',d:'La sanción descrita no es una pena; es una medida de seguridad.'}, correct:'b', why:{b:'Los trabajos en beneficio de la comunidad de 31 días a 1 año son pena menos grave (art.33.3 CP).'}},
{n:173, q:'Los trabajos en beneficio de la comunidad de uno a treinta días, constituyen una pena:', o:{a:'Grave.',b:'Menos Grave.',c:'Leve.',d:'La sanción descrita no es una pena; es una medida de seguridad.'}, correct:'c', why:{c:'Los trabajos en beneficio de la comunidad de 1 a 30 días son pena leve (art.33.4 CP).'}},
{n:174, q:'La privación del derecho a residir en determinados lugares o acudir a ellos por un tiempo de seis meses a cinco años, tiene la consideración de pena:', o:{a:'Leve.',b:'Grave.',c:'Menos grave.',d:'Grave o menos grave, dependiendo de las circunstancias del hecho.'}, correct:'c', why:{c:'La privación del derecho a residir de 6 meses a 5 años es pena menos grave (art.33.3 CP).'}},
{n:175, q:'La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por un tiempo de seis meses a cinco años, tiene la consideración de pena:', o:{a:'Leve.',b:'Grave.',c:'Menos grave.',d:'Grave o menos grave, dependiendo de las circunstancias del hecho.'}, correct:'c', why:{c:'La prohibición de aproximarse de 6 meses a 5 años es pena menos grave (art.33.3 CP).'}},
{n:176, q:'Según el art.33 del Código Penal, es una pena menos grave:', o:{a:'Multa de más de tres meses.',b:'Inhabilitación especial hasta 5 años.',c:'Multa proporcional cualquiera que fuese su cuantía.',d:'Son menos graves las tres penas descritas en las respuestas anteriores.'}, correct:'d', why:{d:'La multa de más de 3 meses, la inhabilitación especial hasta 5 años y la multa proporcional son penas menos graves (art.33.3 CP).'}},
{n:177, q:'Según el art.33 del Código Penal, es una pena menos grave:', o:{a:'La prisión de tres meses a cinco años.',b:'La privación del derecho a residir en determinados lugares o acudir a ellos por tiempo inferior a seis meses.',c:'Prohibición de aproximarse a la víctima, o a sus familiares o personas que determine el Juez o Tribunal por tiempo entre uno y seis meses.',d:'Son menos graves las tres penas descritas en las respuestas anteriores.'}, correct:'a', why:{a:'La prisión de 3 meses a 5 años es una pena menos grave según el art.33.3 CP.'}},
{n:178, q:'La prohibición de comunicarse con la víctima, con aquellos de sus familiares, u otras personas que determine el juez o tribunal, por tiempo de seis meses a cinco años, constituye una pena:', o:{a:'Leve.',b:'Grave.',c:'Menos grave.',d:'Grave o menos grave, dependiendo de las circunstancias del hecho.'}, correct:'c', why:{c:'La prohibición de comunicarse de 6 meses a 5 años es pena menos grave (art.33.3 CP).'}},
{n:179, q:'Para que la pena de multa tenga la consideración de pena menos grave, su duración debe ser superior a...', o:{a:'Los dos meses.',b:'Los tres meses.',c:'Los seis meses.',d:'Los 180 días.'}, correct:'b', why:{b:'La multa de más de 3 meses es pena menos grave; hasta 3 meses es pena leve (art.33.3 y 33.4 CP).'}},
{n:180, q:'La pena de prisión tiene la consideración de grave cuando supera los...', o:{a:'Cuatro años.',b:'Tres años.',c:'Cinco años.',d:'Seis años.'}, correct:'c', why:{c:'La prisión superior a 5 años es pena grave; hasta 5 años es pena menos grave (art.33.2.a y 33.3.a CP).'}},
{n:181, q:'Según el art.33 del Código Penal, es una pena leve:', o:{a:'La privación del derecho a residir en determinados lugares o acudir a ellos por tiempo inferior a seis meses',b:'La prohibición de aproximarse a la víctima, o a sus familiares o personas que determine el Juez o Tribunal por tiempo entre uno y seis meses.',c:'La prohibición de comunicarse con la víctima, o con sus familiares o personas que determine el Juez o Tribunal por tiempo entre uno y seis meses.',d:'Son leves las tres penas descritas en las respuestas anteriores.'}, correct:'d', why:{d:'Las privaciones/prohibiciones de 1 a 6 meses son penas leves según el art.33.4 CP.'}},
{n:182, q:'La pena de prisión permanente revisable...', o:{a:'Tiene una duración entre siete meses y veinte años, salvo lo que excepcionalmente se disponga en el Código Penal.',b:'Puede imponerse por delitos graves y menos graves.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La prisión permanente revisable no tiene esa duración (es indefinida con revisión periódica) y solo se impone por delitos graves específicos.'}},
{n:183, q:'Respecto a las penas aplicables a las personas jurídicas...', o:{a:'Todas ellas tienen la consideración de graves.',b:'Todas ellas tienen la consideración de muy graves.',c:'Todas ellas tienen la consideración de menos graves.',d:'Dependiendo del hecho delictivo que cometan, pueden ser consideradas graves o menos graves.'}, correct:'d', why:{d:'Las penas para personas jurídicas pueden ser graves o menos graves dependiendo del delito cometido (art.33.7 CP).'}},
{n:184, q:'Según el art.33 del Código Penal es una pena grave aplicable a las personas jurídicas:', o:{a:'La multa progresiva y proporcional.',b:'La multa por cuotas o proporcional.',c:'La multa por cuotas o progresiva.',d:'La multa por cuotas, progresiva y proporcional.'}, correct:'b', why:{b:'La multa por cuotas o proporcional es pena grave para personas jurídicas (art.33.7.a CP).'}},
{n:185, q:'Según el art.33 del Código Penal es una pena grave aplicable a las personas jurídicas:', o:{a:'La disolución de la persona jurídica.',b:'La multa por cuotas, progresiva y proporcional.',c:'La suspensión de actividades por un plazo máximo de 8 años.',d:'Inhabilitación para obtener subvenciones y ayudas públicas por un plazo máximo de 5 años.'}, correct:'a', why:{a:'La disolución de la persona jurídica es pena grave aplicable a personas jurídicas (art.33.7.b CP).'}},
{n:186, q:'La pena de disolución de la persona jurídica producirá:', o:{a:'La pérdida definitiva de su personalidad jurídica, así como la de su capacidad de actuar de cualquier modo en el tráfico jurídico.',b:'La pérdida definitiva de su capacidad de llevar a cabo cualquier clase de actividad, aunque sea lícita.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La disolución produce la pérdida definitiva de la personalidad jurídica y de su capacidad de actuar en el tráfico jurídico (art.33.7.b CP).'}},
{n:187, q:'La pena de suspensión de actividades de una persona jurídica tiene una duración máxima de:', o:{a:'6 años.',b:'5 años.',c:'4 años.',d:'10 años.'}, correct:'b', why:{b:'La suspensión de actividades de personas jurídicas tiene una duración máxima de 5 años (art.33.7.c CP).'}},
{n:188, q:'La pena de clausura de locales y establecimientos de una persona jurídica tiene una duración máxima de:', o:{a:'6 años.',b:'5 años.',c:'4 años.',d:'10 años.'}, correct:'b', why:{b:'La clausura de locales de personas jurídicas tiene una duración máxima de 5 años (art.33.7.d CP).'}},
{n:189, q:'La pena de prohibición a la persona jurídica de realizar en el futuro las actividades en cuyo ejercicio se haya cometido, favorecido o encubierto el delito:', o:{a:'Podrá ser temporal o definitiva.',b:'En todo caso será definitiva.',c:'Será definitiva en los casos previstos en el art.32 del Código Penal.',d:'Podrá ser temporal si se cumplen los requisitos previstos en el art.32 del Código Penal.'}, correct:'a', why:{a:'La prohibición de actividades para personas jurídicas puede ser temporal o definitiva (art.33.7.e CP).'}},
{n:190, q:'La pena de prohibición temporal a la persona jurídica de realizar en el futuro las actividades en cuyo ejercicio se haya cometido, favorecido o encubierto el delito:', o:{a:'No podrá exceder de 20 años.',b:'No podrá exceder de 15 años.',c:'No podrá exceder de 10 años.',d:'No podrá exceder de 5 años.'}, correct:'b', why:{b:'La prohibición temporal de actividades para personas jurídicas no puede exceder de 15 años (art.33.7.e CP).'}},
{n:191, q:'Una empresa Calzados es condenada a una pena de inhabilitación para obtener subvenciones y ayudas públicas por un periodo de 5 años. La pena impuesta tiene la consideración de:', o:{a:'Grave.',b:'Menos grave.',c:'Leve.',d:'Ninguna de las anteriores respuestas es cierta.'}, correct:'b', why:{b:'La inhabilitación para obtener subvenciones hasta 5 años es pena menos grave para personas jurídicas (art.33.7 CP).'}},
{n:192, q:'La pena de inhabilitación impuesta a una persona jurídica para obtener subvenciones y ayudas públicas no podrá exceder de:', o:{a:'15 años.',b:'12 años.',c:'10 años.',d:'5 años.'}, correct:'a', why:{a:'La inhabilitación para obtener subvenciones de personas jurídicas no puede exceder de 15 años (art.33.7.f CP).'}},
{n:193, q:'La pena de intervención judicial impuesta a una persona jurídica para salvaguardar los derechos de los trabajadores o de los acreedores por el tiempo que se estime necesario:', o:{a:'No podrá exceder de 15 años.',b:'No podrá exceder de 12 años.',c:'No podrá exceder de 10 años.',d:'No podrá exceder de 5 años.'}, correct:'d', why:{d:'La intervención judicial de personas jurídicas no puede exceder de 5 años (art.33.7.g CP).'}},
{n:194, q:'Según el art.34 del Código penal, no se reputarán penas:', o:{a:'La detención y prisión preventiva y las demás medidas cautelares de naturaleza penal.',b:'Las multas y demás correcciones que, en uso de atribuciones gubernativas o disciplinarias, se impongan a los subordinados o administrados.',c:'Las privaciones de derechos y las sanciones reparadoras que establezcan las leyes civiles o administrativas.',d:'Ninguna de las descritas en las respuestas anteriores.'}, correct:'d', why:{d:'El art.34 CP establece que no se reputan penas todas las mencionadas en las opciones a, b y c.'}},
{n:195, q:'Indique cuál de las siguientes se considera pena privativa de libertad.', o:{a:'La localización permanente.',b:'La responsabilidad personal subsidiaria por impago de multa.',c:'La prisión.',d:'Conforme dispone el art.35 del Código Penal, todas las descritas en las respuestas anteriores son penas privativas de libertad.'}, correct:'d', why:{d:'El art.35 CP establece que son penas privativas de libertad la prisión, la localización permanente y la responsabilidad personal subsidiaria por impago de multa.'}},
{n:196, q:'La pena de prisión permanente será revisada:', o:{a:'De conformidad con lo dispuesto en el artículo 92 CP.',b:'De conformidad con lo dispuesto en el artículo 82 CP.',c:'De conformidad con lo dispuesto en el artículo 72 CP.',d:'De conformidad con lo dispuesto en el artículo 62 CP.'}, correct:'a', why:{a:'La revisión de la prisión permanente revisable se regula en el art.92 del CP.'}},
{n:197, q:'Durante el cumplimiento de la pena de prisión permanente, la clasificación del condenado en el tercer grado deberá ser autorizada por el tribunal, previo pronóstico individualizado y favorable de reinserción social...', o:{a:'Oídos el Ministerio Fiscal e Instituciones Penitenciarias.',b:'Previo informes psicológicos del equipo de tratamiento, que no serán vinculantes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Para clasificar en tercer grado con prisión permanente se requiere oír al Ministerio Fiscal e Instituciones Penitenciarias (art.36.1 CP).'}},
{n:198, q:'Durante el cumplimiento de la pena de prisión permanente, la clasificación del condenado en el tercer grado deberá ser autorizada por el tribunal, previo pronóstico individualizado y favorable de reinserción social, oído el Ministerio Fiscal e Instituciones Penitenciarias, y no podrá efectuarse:', o:{a:'Hasta el cumplimiento de 20 años de prisión efectiva, en el caso de que el penado lo hubiera sido por un delito del Capítulo VII del Título XXII del Libro II del CP.',b:'Hasta el cumplimiento de quince años de prisión efectiva, en el caso de que el penado lo hubiera sido por un delito no comprendido en el Capítulo VII del Título XXII del Libro II del CP.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.36.1 CP establece ambos plazos mínimos para clasificar en tercer grado con prisión permanente revisable.'}},
{n:199, q:'Durante el cumplimiento de la pena de prisión permanente, en el caso de que el penado lo hubiera sido por un delito del Capítulo VII del Título XXII del Libro II del CP, no podrá disfrutar de permisos de salida:', o:{a:'Hasta que haya cumplido un mínimo de quince años de prisión.',b:'Hasta que haya cumplido un mínimo de doce años de prisión.',c:'Hasta que haya cumplido un mínimo de diez años de prisión.',d:'Hasta que haya cumplido un mínimo de ocho años de prisión.'}, correct:'b', why:{b:'Para delitos del Capítulo VII Título XXII Libro II, los permisos de salida no son posibles hasta cumplir 12 años de prisión (art.36.1 CP).'}},
{n:200, q:'Durante el cumplimiento de la pena de prisión permanente, en el caso de que el penado lo hubiera sido por un delito no comprendido en el Capítulo VII del Título XXII del Libro II del CP, no podrá disfrutar de permisos de salida:', o:{a:'Hasta que haya cumplido un mínimo de quince años de prisión.',b:'Hasta que haya cumplido un mínimo de doce años de prisión.',c:'Hasta que haya cumplido un mínimo de diez años de prisión.',d:'Hasta que haya cumplido un mínimo de ocho años de prisión.'}, correct:'d', why:{d:'Para delitos no comprendidos en el Cap. VII, los permisos de salida no son posibles hasta cumplir 8 años (art.36.1 CP).'}},
{n:201, q:'Con respecto a la pena de prisión, según lo dispuesto en el Código Penal...', o:{a:'Tendrá una duración mínima de tres meses y máxima de veinte años, salvo lo que excepcionalmente dispongan otros preceptos del CP.',b:'Cuando la duración de la pena de prisión impuesta sea superior a ocho años, el juez o tribunal podrá ordenar que la clasificación del condenado en el tercer grado de tratamiento penitenciario no se efectúe hasta el cumplimiento de dos tercios de la pena impuesta.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La pena de prisión tiene una duración mínima de 3 meses y máxima de 20 años, salvo excepciones (art.36.2 CP).'}},
{n:202, q:'Con respecto a la pena de prisión, según lo dispuesto en el Código Penal...', o:{a:'Cuando la duración de la pena de prisión impuesta sea superior a cinco años, el juez o tribunal podrá ordenar que la clasificación del condenado en el tercer grado de tratamiento penitenciario no se efectúe hasta el cumplimiento de la mitad de la pena impuesta.',b:'Cuando la duración de la pena de prisión impuesta sea superior a cinco años y se trate de delitos referentes a grupos terroristas, la clasificación del condenado en el tercer grado de tratamiento penitenciario no podrá efectuarse hasta el cumplimiento de la mitad de la misma.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Para delitos terroristas con pena de prisión superior a 5 años, la clasificación en tercer grado no puede efectuarse hasta cumplir la mitad (art.36.2 CP).'}},
{n:203, q:'Cuando la duración de la pena de prisión impuesta sea superior a cinco años, la clasificación del condenado en tercer grado de tratamiento penitenciario no podrá efectuarse hasta el cumplimiento de la mitad de la misma, cuando la condena sea:', o:{a:'Por delitos del artículo 181.',b:'Por delitos del Capítulo V del Título VIII del Libro II de este Código, cuando la víctima sea menor de dieciséis años.',c:'Por delitos del Título VII bis del Libro II del Código Penal, cuando la víctima sea una persona menor de edad o una persona con discapacidad necesitada de especial protección.',d:'Por cualquiera de los delitos descritos en las respuestas a y b, y en ninguno de estos casos podrá efectuarse dicha clasificación sin valoración e informe específico acerca del aprovechamiento por el reo del programa de tratamiento para condenados por agresión sexual.'}, correct:'d', why:{d:'El art.36.2 CP establece que la restricción del tercer grado aplica para delitos del Cap. V Título VIII (menores de 16) y del Título VII bis, con informe específico.'}},
{n:204, q:'Cuando la duración de la pena de prisión impuesta sea superior a cinco años, la clasificación del condenado en tercer grado de tratamiento penitenciario no podrá efectuarse hasta el cumplimiento de la mitad de la misma, cuando la condena sea:', o:{a:'Por delitos referentes a organizaciones y grupos terroristas y delitos de terrorismo del Capítulo VII del Título XXII del Libro II del Código Penal.',b:'Por delitos cometidos en el seno de una organización o grupo criminal.',c:'Por cualquiera de los delitos descritos en las respuestas a y b.',d:'Todas las respuestas son incorrectas.'}, correct:'a', why:{a:'El art.36.2 CP restringe el tercer grado hasta cumplir la mitad para delitos de terrorismo del Cap. VII Título XXII Libro II.'}},
{n:205, q:'La autoridad judicial de vigilancia penitenciaria, podrá acordar, previo informe del Ministerio Fiscal, Instituciones Penitenciarias y las demás partes, la progresión a tercer grado por motivos humanitarios y de dignidad personal de:', o:{a:'Penados enfermos muy graves con padecimientos incurables, valorando especialmente su escasa peligrosidad.',b:'Penados septuagenarios, valorando especialmente su escasa peligrosidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.36.3 CP permite la progresión al tercer grado por motivos humanitarios a enfermos muy graves y a penados septuagenarios.'}},
{n:206, q:'El art.37 del Código Penal dispone que la pena de localización permanente tendrá una duración de:', o:{a:'Hasta doce meses.',b:'Hasta seis meses.',c:'Hasta cinco meses.',d:'Hasta tres meses.'}, correct:'a', why:{a:'La pena de localización permanente tiene una duración de hasta 12 meses (art.37 CP).'}},
{n:207, q:'El cumplimiento de una pena de localización permanente obliga al penado:', o:{a:'A permanecer en su domicilio o en lugar determinado fijado por el Juez en sentencia o posteriormente en auto motivado.',b:'A permanecer en su domicilio o cualquier otro lugar que él haya solicitado motivadamente y el Juez lo haya estimado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La localización permanente obliga al penado a permanecer en su domicilio o lugar determinado por el juez (art.37 CP).'}},
{n:208, q:'En los casos en los que la localización permanente esté prevista como pena principal, atendiendo a la reiteración en la comisión de la infracción y siempre que así lo disponga expresamente el concreto precepto aplicable, el Juez podrá acordar en sentencia:', o:{a:'Que se cumpla a intervalos o de forma continuada, ya sea en el domicilio del penado o en centro penitenciario más próximo a éste.',b:'Que se cumpla los sábados, domingos y días festivos en el centro penitenciario más próximo al domicilio del penado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.37.1 CP permite que la localización permanente se cumpla en el domicilio o en centro penitenciario, de forma continuada o a intervalos.'}},
{n:209, q:'Si el reo lo solicitare y las circunstancias lo aconsejaren, oído el ministerio fiscal, el juez o tribunal sentenciador de una pena de localización permanente podrá acordar:', o:{a:'Que la condena se cumpla durante los sábados y domingos.',b:'Que la condena se cumpla de forma no continuada.',c:'Que la condena se cumpla de alguna de las formas descritas en las respuestas a) y b).',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art.37.1 CP permite que a petición del reo la pena se cumpla los fines de semana o de forma no continuada.'}},
{n:210, q:'Respecto al cumplimiento de las penas de localización permanente, señale la afirmación incorrecta:', o:{a:'Si el condenado incumpliera la pena, el juez o tribunal sentenciador deducirá testimonio para proceder de conformidad con lo que dispone el art.368 del CP.',b:'Para garantizar el cumplimiento efectivo, el Juez o Tribunal podrá acordar la utilización de medios mecánicos o electrónicos que permitan la localización del reo.',c:'Cuando el reo estuviere preso, la duración de las penas empezará a computarse desde el día en que la sentencia condenatoria haya quedado firme.',d:'Cuando el reo no estuviere preso, la duración de las penas empezará a contarse desde que ingrese en el establecimiento adecuado para su cumplimiento.'}, correct:'a', why:{a:'El art.37 CP establece que si se incumple la localización permanente se deducirá testimonio conforme al art.468 CP, no al art.368 CP.'}},
{n:211, q:'Si el condenado incumpliera la pena impuesta de localización permanente, el juez o tribunal sentenciador:', o:{a:'Deducirá testimonio para proceder de conformidad con lo que dispone el art.468 del CP.',b:'Deducirá testimonio para proceder de conformidad con lo que dispone el art.368 del CP.',c:'Deducirá testimonio para proceder de conformidad con lo que dispone el art.469 del CP.',d:'Deducirá testimonio para proceder de conformidad con lo que dispone el art.369 del CP.'}, correct:'a', why:{a:'El incumplimiento de la localización permanente se trata conforme al art.468 CP (quebrantamiento de condena).'}},
{n:212, q:'Según el artículo 39 del Código Penal, son penas privativas de derechos:', o:{a:'La inhabilitación absoluta, la suspensión de empleo o cargo público, los trabajos en beneficio de la comunidad y la privación de la patria potestad.',b:'Las de inhabilitación especial para empleo o cargo público, profesión, oficio, industria o comercio, u otras actividades, sean o no retribuidas, o de los derechos de patria potestad, tutela, guarda o curatela, tenencia de animales, derecho de sufragio pasivo o de cualquier otro derecho.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.39 CP contempla como privativas de derechos tanto las mencionadas en a) como en b).'}},
{n:213, q:'Según el artículo 39 del Código Penal, son penas privativas de derechos:', o:{a:'La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez y la privación del derecho a residir en determinados lugares o acudir a ellos.',b:'La prohibición de comunicarse con la víctima y la prohibición del derecho a residir en determinados lugares.',c:'La localización permanente, la libertad vigilada y la custodia familiar.',d:'Todas las citadas en las respuestas anteriores son penas privativas de derechos según dicho artículo.'}, correct:'d', why:{d:'El art.39 CP incluye como privativas de derechos todas las mencionadas.'}},
{n:214, q:'La prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el juez o tribunal...', o:{a:'Impide al penado acudir al lugar en que haya cometido el delito, o a aquel en que resida la víctima o su familia, si fueren distintos.',b:'Impide al penado establecer con ellas, por cualquier medio de comunicación o medio informático o telemático, contacto escrito, verbal o visual.',c:'Impide al penado acudir al lugar en que haya cometido el delito, o a aquél en que resida la víctima o su familia, si fueren distintos.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La prohibición de comunicarse impide al penado establecer cualquier contacto por cualquier medio con las personas designadas (art.48 CP).'}},
{n:215, q:'El art.40 del Código Penal dispone que la pena de inhabilitación absoluta:', o:{a:'Tendrá una duración de 3 meses a 10 años.',b:'Tendrá una duración de 6 a 20 años.',c:'Tendrá una duración de 3 meses a 6 años',d:'Tendrá una duración de 6 a 10 años.'}, correct:'b', why:{b:'La inhabilitación absoluta tiene una duración de 6 a 20 años (art.40 CP).'}},
{n:216, q:'La pena de inhabilitación absoluta produce la privación definitiva de todos los honores, empleos y cargos públicos que tenga el penado, aunque quean electivos, y la incapacidad para obtener los mismos o cualesquiera otros honores, cargos o empleos públicos, y la de ser elegido para cargo público:', o:{a:'Durante el tiempo de la condena.',b:'Definitivamente.',c:'Por un período máximo de 15 años.',d:'Durante el plazo comprendido entre los 3 meses y 15 años.'}, correct:'a', why:{a:'La inhabilitación absoluta produce sus efectos durante el tiempo de la condena (art.41 CP).'}},
{n:217, q:'El art.40 del Código Penal dispone que la pena de inhabilitación especial:', o:{a:'Tendrá una duración de 3 meses a 20 años.',b:'Tendrá una duración de 6 a 20 años.',c:'Tendrá una duración de 3 meses a 6 años',d:'Tendrá una duración de 6 a 10 años.'}, correct:'b', why:{b:'La inhabilitación especial tiene una duración de 6 meses a 20 años (art.40 CP).'}},
{n:218, q:'Respecto a la pena de inhabilitación especial para empleo o cargo público, indique la afirmación incorrecta:', o:{a:'Esta pena produce la privación definitiva del empleo o cargo sobre el que recayere, aunque sea electivo, y de los honores que le sean anejos.',b:'Esta pena produce la incapacidad para obtener el mismo empleo o cargo u otros análogos, durante el tiempo de la condena.',c:'En la sentencia que se dicte habrán de especificarse los empleos, cargos y honores sobre los que recae la inhabilitación.',d:'La inhabilitación especial para el derecho de sufragio pasivo, durante el tiempo de la condena no priva al penado del derecho a ser elegido para cargos públicos.'}, correct:'d', why:{d:'La inhabilitación especial para el sufragio pasivo SÍ priva al penado del derecho a ser elegido para cargos públicos durante la condena.'}},
{n:219, q:'La inhabilitación especial para profesión, oficio, industria o comercio u otras actividades, sean o no retribuidas, o cualquier otro derecho, que ha de concretarse expresa y motivadamente en la sentencia:', o:{a:'Priva a la persona penada de la facultad de ejercerlos durante el tiempo de la condena.',b:'En su aplicación la autoridad judicial podrá restringir la inhabilitación a determinadas actividades o funciones de la profesión u oficio, retribuido o no, permitiendo, si ello fuera posible, el ejercicio de aquellas funciones no directamente relacionadas con el delito cometido',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La inhabilitación especial para profesión priva de su ejercicio durante la condena y puede restringirse a determinadas funciones (art.45 CP).'}},
{n:220, q:'La inhabilitación especial para el ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento:', o:{a:'Priva a la persona condenada de los derechos inherentes a la patria potestad.',b:'Supone la extinción del ejercicio de la tutela, curatela, guarda o acogimiento, así como la incapacidad para obtener nombramiento para dichos cargos durante el tiempo de la condena.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La inhabilitación especial para patria potestad produce los efectos descritos en ambas opciones (art.46 CP).'}},
{n:221, q:'Respecto a las penas privativas de derechos, indique la afirmación incorrecta:', o:{a:'La pena de privación de la patria potestad implica la pérdida de la titularidad de la misma, subsistiendo aquellos derechos de los que sea titular el hijo o la hija respecto de la persona condenada que se determinen judicialmente.',b:'La inhabilitación especial para el derecho de sufragio pasivo, durante el tiempo de la condena no priva al penado del derecho a ser elegido para cargos públicos.',c:'La autoridad judicial podrá acordar la pena de privación de la patria potestad respecto de todas o algunas de las personas menores de edad o personas con discapacidad necesitadas de especial protección que estén a cargo de la persona condenada.',d:'La pena de suspensión de empleo o cargo público priva de su ejercicio al penado durante el tiempo de la condena.'}, correct:'b', why:{b:'La inhabilitación especial para el derecho de sufragio pasivo SÍ priva del derecho a ser elegido, siendo esa afirmación incorrecta.'}},
{n:222, q:'El art.40 del Código Penal dispone que la pena de suspensión de empleo o cargo público:', o:{a:'Tendrá una duración de 3 meses a 20 años.',b:'Tendrá una duración de 6 a 20 años.',c:'Tendrá una duración de 3 meses a 6 años',d:'Tendrá una duración de 6 a 10 años.'}, correct:'b', why:{b:'La suspensión de empleo o cargo público tiene una duración de 6 meses a 6 años según el art.40 CP.'}},
{n:223, q:'El art.40 del Código Penal dispone que la pena de privación del derecho a conducir vehículos a motor y ciclomotores, y la de privación del derecho a la tenencia y porte de armas:', o:{a:'Tendrán una duración de 3 meses a 10 años.',b:'Tendrán una duración de 6 a 20 años.',c:'Tendrán una duración de 3 meses a 6 años',d:'Tendrán una duración de 6 a 10 años.'}, correct:'a', why:{a:'Las privaciones del derecho a conducir y a tenencia de armas tienen una duración de 3 meses a 10 años (art.40 CP).'}},
{n:224, q:'El art.40 del Código Penal dispone la duración de la pena de privación del derecho a conducir vehículos a motor y ciclomotores, y la de privación del derecho a la tenencia y porte de armas, y su imposición:', o:{a:'Inhabilitará al penado para el ejercicio de estos derechos durante el tiempo fijado en la sentencia.',b:'Cuando la pena impuesta lo fuere por un tiempo superior a dos años comportará la pérdida de vigencia del permiso o licencia que habilite para la conducción o la tenencia y porte, respectivamente.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'La privación del derecho a conducir o a la tenencia de armas inhabilita para el ejercicio y, si supera 2 años, comporta la pérdida del permiso (art.47 CP).'}},
{n:225, q:'El art.40 del Código Penal dispone que la pena de privación del derecho a residir en determinados lugares o acudir a ellos tendrá una duración de:', o:{a:'Hasta 20 años.',b:'Hasta 15 años.',c:'Hasta 10 años.',d:'Hasta 5 años.'}, correct:'b', why:{b:'La pena de privación del derecho a residir en determinados lugares tiene una duración de hasta 15 años (art.40 CP).'}},
{n:226, q:'Respecto a la pena de privación del derecho a residir en determinados lugares o acudir a ellos, indique la afirmación incorrecta', o:{a:'Tendrá una duración de hasta 15 años.',b:'Impide al penado residir en el lugar en que haya cometido el delito, o en aquel en que resida la víctima o su familia, si fueren distintos.',c:'En los casos en que exista declarada una discapacidad intelectual o una discapacidad que tenga su origen en un trastorno mental, se estudiará el caso concreto a fin de resolver teniendo presentes los bienes jurídicos a proteger y el interés superior de la persona con discapacidad que, en su caso, habrá de contar con los medios de acompañamiento y apoyo precisos para el cumplimiento de la medida.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La opción a es la afirmación incorrecta: dice que la pena tiene una duración de hasta 15 años, pero el art.40 CP establece que la pena de privación del derecho a residir tiene una duración de hasta 10 años.'}},
{n:227, q:'El art.40 del Código Penal dispone que la pena de prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas, o de comunicarse con ellas:', o:{a:'Tendrá una duración de 3 meses a 6 años',b:'Tendrá una duración de 6 a 10 años.',c:'Tendrá una duración de 3 meses a 10 años.',d:'Tendrá una duración de 1 mes a 10 años.'}, correct:'c', why:{c:'La prohibición de aproximarse o comunicarse tiene una duración de 3 meses a 10 años (art.40 CP).'}},
{n:228, q:'Respecto a la pena de prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas, o de comunicarse con ellas, indique la afirmación incorrecta:', o:{a:'La prohibición de aproximarse a la víctima, familiares, u otras personas, impide al penado acercarse a ellos, en cualquier lugar donde se encuentren, así como acercarse a su domicilio, a sus lugares de trabajo o de descanso, o a cualquier otro que sea frecuentado por aquél, quedando en suspenso, respecto al régimen de visitas, comunicación y estancia con los hijos y, en su caso, se hubiere reconocido en sentencia civil hasta el total de esta pena.',b:'Tendrá una duración de 3 meses a 10 años.',c:'La prohibición de comunicarse con la víctima, o con aquellos de sus familiares u otras personas que determine el juez o tribunal, impide al penado establecer con ellas, por cualquier medio de comunicación o medio informático o telemático, contacto escrito, verbal o visual.',d:'El juez o tribunal podrá acordar que el control de estas medidas se realice a través de aquellos medios electrónicos que lo permitan.'}, correct:'a', why:{a:'La descripción de la opción a es incorrecta porque la suspensión del régimen de visitas no queda en suspenso automáticamente, sino que el juez lo decidirá.'}},
{n:229, q:'El art.40 del Código Penal dispone que la pena de trabajos en beneficio de la comunidad:', o:{a:'Tendrá una duración de 3 meses a 6 años',b:'Tendrá una duración de un día a un año.',c:'Tendrá una duración de 3 meses a 10 años.',d:'Tendrá una duración de un mes a 10 años.'}, correct:'b', why:{b:'Los trabajos en beneficio de la comunidad tienen una duración de 1 día a 1 año (art.40 CP).'}},
{n:230, q:'Los trabajos en beneficio de la comunidad, impuestos como pena privativa de derechos:', o:{a:'No podrán imponerse sin el consentimiento de la persona condenada y su duración diaria no podrá exceder de ocho horas.',b:'Obligan a prestar su cooperación no retribuida en determinadas actividades de utilidad pública.',c:'Podrán consistir, en relación con delitos de similar naturaleza al cometido por la persona condenada, en labores de reparación de los daños causados o de apoyo o asistencia a las víctimas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Los trabajos en beneficio de la comunidad requieren consentimiento, implican cooperación no retribuida y pueden consistir en labores de reparación (art.49 CP).'}},
{n:231, q:'Los trabajos en beneficio de la comunidad, impuestos como pena privativa de derechos:', o:{a:'Podrán consistir, en relación con delitos de similar naturaleza al cometido por la persona condenada, en labores de reparación de los daños causados o de apoyo o asistencia a las víctimas.',b:'Podrán consistir en la participación del penado en talleres o programas formativos de reeducación, laborales, culturales, de educación vial, sexual, resolución pacífica de conflictos, parentalidad positiva y otros similares.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Los trabajos en beneficio de la comunidad pueden incluir labores de reparación y participación en talleres formativos (art.49 CP).'}},
{n:232, q:'Respecto a las condiciones en que han de realizarse los trabajos en beneficio de la comunidad, impuestos como pena privativa de derechos, indique la afirmación incorrecta:', o:{a:'La ejecución se desarrollará bajo el control del Juez de Vigilancia Penitenciaria, que, a tal efecto, requerirá los informes sobre el desempeño del trabajo a la Administración, entidad pública o asociación de interés general en que se presten los servicios.',b:'No atentará a la dignidad del penado.',c:'Podrá supeditarse al logro de intereses económicos',d:'El trabajo en beneficio de la comunidad será facilitado por la Administración, la cual podrá establecer los convenios oportunos a tal fin.'}, correct:'c', why:{c:'Los trabajos en beneficio de la comunidad NO pueden supeditarse al logro de intereses económicos (art.49 CP).'}},
{n:233, q:'Respecto a las condiciones en que han de realizarse los trabajos en beneficio de la comunidad, impuestos como pena privativa de derechos, indique la afirmación incorrecta:', o:{a:'Gozará de la protección dispensada a los penados por la legislación penitenciaria en materia de Seguridad Social.',b:'El trabajo en beneficio de la comunidad podrá ser facilitado por el sector privado, previo acuerdos firmados con la Administración.',c:'No se supeditará al logro de intereses económicos.',d:'Los servicios sociales penitenciarios, hechas las verificaciones necesarias, comunicarán al Juez de Vigilancia Penitenciaria las incidencias relevantes de la ejecución de la pena.'}, correct:'b', why:{b:'El trabajo en beneficio de la comunidad lo facilita la Administración, no el sector privado directamente mediante acuerdos.'}},
{n:234, q:'Respecto al cumplimiento de la pena de trabajos en beneficio de la comunidad, los servicios sociales penitenciarios, hechas las verificaciones necesarias, comunicarán al Juez de Vigilancia Penitenciaria, en todo caso, si el penado:', o:{a:'Se ausenta del trabajo durante al menos dos jornadas laborales, siempre que ello suponga un rechazo voluntario por su parte al cumplimiento de la pena.',b:'A pesar de los requerimientos del responsable del centro de trabajo, su rendimiento fuera sensiblemente inferior al mínimo exigible.',c:'Se opusiera o incumpliera de forma reiterada y manifiesta las instrucciones que se le dieren por el responsable de la ocupación, referidas al desarrollo de la misma.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Los servicios sociales comunicarán al JVP en todos los casos descritos (art.49 CP).'}},
{n:235, q:'Tras recibir una comunicación de los servicios sociales penitenciarios, respecto al cumplimiento de una pena de trabajos en beneficio de la comunidad, el Juez de Vigilancia Penitenciaria, una vez valorado el informe, podrá:', o:{a:'Acordar su ejecución en el mismo centro.',b:'Enviar al penado para que finalice la ejecución de la misma en otro centro.',c:'Entender que el penado ha incumplido la pena.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El JVP podrá adoptar cualquiera de esas decisiones tras recibir el informe de servicios sociales.'}},
{n:236, q:'Respecto a las condiciones en que han de realizarse los trabajos en beneficio de la comunidad, impuestos como pena privativa de derechos, si el penado faltara del trabajo por causa justificada:', o:{a:'No se entenderá como abandono de la actividad.',b:'El trabajo perdido no se le computará en la liquidación de la condena.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Si la falta es por causa justificada, no se entiende como abandono de la actividad (art.49 CP).'}},
{n:237, q:'La duración de las penas privativas de derechos será la prevista en el art.40 del Código Penal para cada una de ellas:', o:{a:'Salvo lo que excepcionalmente dispongan otros preceptos del propio Código Penal.',b:'Dependiendo de que la sentencia sea firme o no.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La duración de las penas privativas de derechos es la del art.40 CP, salvo que otros preceptos dispongan otra cosa.'}},
{n:238, q:'El Código Penal regula la pena de multa en sus artículos:', o:{a:'53 a 60.',b:'50 a 53.',c:'60 a 63.',d:'49 a 55.'}, correct:'b', why:{b:'La pena de multa está regulada en los artículos 50 a 53 del CP.'}},
{n:239, q:'En la pena de multa se distingue entre:', o:{a:'Sistema de días-multa y la multa proporcional.',b:'Sistema proporcional, sistema de días-multa y sistema pecuniario progresivo.',c:'Sistema de días-multa, sistema pecuniario progresivo y la multa restitutiva.',d:'Sistema pecuniario progresivo y sistema días-multa por plazos.'}, correct:'a', why:{a:'El CP distingue entre el sistema de días-multa y la multa proporcional (art.50 CP).'}},
{n:240, q:'Según establece el art.50 del Código Penal:', o:{a:'La pena de multa consistirá en la imposición al condenado de una sanción pecuniaria.',b:'La pena de multa se impondrá, salvo que la Ley disponga otra cosa, por el sistema de días-multa.',c:'Su extensión mínima será de diez días y la máxima de dos años. Las penas de multa imponibles a personas jurídicas tendrán una extensión máxima de cinco años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.50 CP establece todo lo descrito: la multa como sanción pecuniaria, el sistema de días-multa y las extensiones mínimas y máximas.'}},
{n:241, q:'Según lo establecido en el art.50 del Código Penal, respecto a la pena de multa, indique la afirmación incorrecta:', o:{a:'La cuota diaria tendrá un mínimo de dos y un máximo de 400 euros.',b:'En las multas imponibles a las personas jurídicas la cuota diaria tendrá un mínimo de 30 y un máximo de 5.000 euros.',c:'A efectos de computo, los fines de semana computarán siempre a cuatro por mes.',d:'A efectos de cómputo, cuando se fije la duración por meses o por años, se entenderá que los meses son de treinta días y los años de trescientos sesenta.'}, correct:'c', why:{c:'Los fines de semana no se computan a cuatro por mes. Esta afirmación es incorrecta.'}},
{n:242, q:'Según lo establecido en los artículos 50 y 51 del Código Penal, respecto a la pena de multa, indique la afirmación incorrecta:', o:{a:'Los Jueces o Tribunales determinarán motivadamente la extensión de la pena dentro de los límites establecidos para cada delito y según las reglas del capítulo II de este Título.',b:'Los Jueces o Tribunales fijarán en la sentencia, el importe de estas cuotas, teniendo en cuenta para ello exclusivamente la situación económica del reo, deducida de su patrimonio, ingresos, obligaciones y cargas familiares y demás circunstancias personales del mismo.',c:'Los Jueces o Tribunales podrán autorizar el pago de la multa dentro de un plazo que no exceda de tres años desde la firmeza de la sentencia, bien de una vez o en los plazos que se determinen. En este caso, el impago de tres de ellos determinará el vencimiento de los restantes.',d:'Si, después de la sentencia, variase la situación económica del penado, el juez o tribunal, excepcionalmente y tras la debida indagación de dicha situación, podrá modificar tanto el importe de las cuotas periódicas como los plazos para su pago.'}, correct:'b', why:{b:'La cuota de la multa no se fija atendiendo EXCLUSIVAMENTE a la situación económica; también se considera la extensión del perjuicio causado por el delito.'}},
{n:243, q:'Según el art.50.6. del código Penal, el tribunal, por causa justificada, podrá autorizar el pago de la multa:', o:{a:'Dentro de un plazo que no exceda de dos años desde la firmeza de la sentencia, bien de una vez o en los plazos que se determinen.',b:'Dentro de un plazo que no exceda de tres años desde la firmeza de la sentencia, bien de una vez o en los plazos que se determinen.',c:'Dentro de un plazo que no exceda de un año desde la firmeza de la sentencia, bien de una vez o en los plazos que se determinen.',d:'Dentro de un plazo que no exceda de cinco años desde que la sentencia sea firme.'}, correct:'b', why:{b:'El art.50.6 CP permite autorizar el pago de la multa en un plazo máximo de 3 años desde la firmeza de la sentencia.'}},
{n:244, q:'Cuando el tribunal, por causa justificada, autorice los plazos establecido en el art.50.6. del Código Penal para la pena de multa...', o:{a:'El impago de cinco de ellos determinará el vencimiento de los restantes.',b:'El impago de cuatro de ellos determinará el vencimiento de los restantes.',c:'El impago de tres de ellos determinará el vencimiento de los restantes.',d:'El impago de dos de ellos determinará el vencimiento de los restantes.'}, correct:'c', why:{c:'El impago de tres de los plazos determinará el vencimiento de los restantes (art.50.6 CP).'}},
{n:245, q:'Cuando el Código Penal así lo determine, la pena de multa se establecerá:', o:{a:'En proporción al daño causado, el valor del objeto del delito o el beneficio reportado por el mismo.',b:'Dentro de un plazo que no exceda de tres años desde la firmeza de la sentencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La multa proporcional se establece en proporción al daño causado, valor del objeto o beneficio obtenido (art.52 CP).'}},
{n:246, q:'Cuando el Código Penal así lo determine para la imposición de la pena de multa proporcional, los jueces y tribunales impondrán la multa dentro de los límites fijados para cada delito, considerando, para determinar en cada caso su cuantía:', o:{a:'Las circunstancias atenuantes y agravantes del hecho.',b:'Principalmente la situación económica del culpable.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Para determinar la cuantía de la multa proporcional se consideran las circunstancias del hecho y la situación económica del culpable.'}},
{n:247, q:'Si, después de la sentencia, empeorase la situación económica del penado con una multa, el juez o tribunal, excepcionalmente y tras la debida indagación de dicha situación:', o:{a:'Reducirá el importe de la multa y autorizará su pago en un plazo que no podrá exceder de los tres años.',b:'Podrá reducir el importe de la multa dentro de los límites señalados por la ley para el delito de que se trate, o autorizar su pago en los plazos que se determinen.',c:'Reducirá el importe de la multa y autorizará su pago en un plazo que no podrá exceder de los dos años.',d:'Reducirá el importe de la multa y autorizará el pago en un plazo que no podrá exceder de un año.'}, correct:'b', why:{b:'Si empeora la situación económica, el juez podrá reducir la multa o autorizar plazos (art.51 CP).'}},
{n:248, q:'En los casos en que el Código Penal prevé una pena de multa para las personas jurídicas en proporción al beneficio obtenido o facilitado, al perjuicio causado, al valor del objeto, o a la cantidad defraudada o indebidamente obtenida, de no ser posible el cálculo en base a tales conceptos, el Juez o Tribunal motivará la imposibilidad de proceder a tal cálculo y las multas previstas se sustituirán por la siguiente:', o:{a:'Multa de dos a cinco años, si el delito cometido por la persona física tiene prevista una pena de prisión de más de cinco años.',b:'Multa de tres meses a cinco años, si el delito cometido por la persona física tiene prevista una pena de prisión de más de cinco años no incluida en el inciso anterior.',c:'Multa de seis meses a dos años, en el resto de los casos.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Cuando no se puede calcular la multa proporcional para personas jurídicas, se sustituye por multa de 2 a 5 años si la pena de prisión es de más de 5 años (art.52.4 CP).'}},
{n:249, q:'En los casos en que el Código Penal prevé una pena de multa para las personas jurídicas en proporción al beneficio obtenido o facilitado, al perjuicio causado, al valor del objeto, o a la cantidad defraudada o indebidamente obtenida, de no ser posible el cálculo en base a tales conceptos, el Juez o Tribunal motivará la imposibilidad de proceder a tal cálculo y las multas previstas se sustituirán por la siguiente:', o:{a:'Multa de dos a cinco años, si el delito cometido por la persona física tiene prevista una pena de prisión de más de cinco años.',b:'Multa de uno a tres años, si el delito cometido por la persona física tiene prevista una pena de prisión de más de dos años no incluida en el inciso anterior.',c:'Multa de seis meses a dos años, en el resto de los casos citados en las respuestas anteriores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.52.4 CP establece los tres tramos de sustitución de la multa proporcional para personas jurídicas: 2-5 años, 1-3 años y 6 meses-2 años.'}},
{n:250, q:'El art.53 del Código Penal establece que, si el condenado no satisficiere, voluntariamente o por vía de apremio la multa impuesta:', o:{a:'Quedará sujeto a una responsabilidad personal subsidiaria de tres días de privación de libertad por cada dos cuotas diarias no satisfechas.',b:'Quedará sujeto a una responsabilidad personal subsidiaria de un día de privación de libertad por cada cuota diaria no satisfecha.',c:'Quedará sujeto a una responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas.',d:'Quedará sujeto a una responsabilidad personal subsidiaria de dos días de privación de libertad por cada cuota diaria no satisfecha.'}, correct:'c', why:{c:'El art.53.1 CP establece: quedará sujeto a responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas.'}},
{n:251, q:'El art.53 del Código Penal establece que, si el condenado no satisficiere, voluntariamente o por vía de apremio la multa impuesta, tratándose de delitos leves:', o:{a:'Podrá cumplirse mediante localización permanente.',b:'Quedará sujeto a una responsabilidad personal subsidiaria de un día de privación de libertad por cada cuota diaria no satisfecha.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'En delitos leves, el impago de multa puede cumplirse mediante localización permanente (art.53.1 CP).'}},
{n:252, q:'El art.53 del Código Penal establece que, si el condenado no satisficiere, voluntariamente o por vía de apremio la multa impuesta:', o:{a:'Quedará sujeto a una responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas.',b:'Podrá cumplirse mediante localización permanente, tratándose de delitos leves.',c:'El juez o tribunal, previa conformidad del penado, podrá acordar que la responsabilidad subsidiaria se cumpla mediante trabajos en beneficio de la comunidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.53 CP establece todos esos modos de cumplir la responsabilidad subsidiaria por impago de multa.'}},
{n:253, q:'Según establece el art.53 del Código Penal, en caso de que el juez o tribunal, previa conformidad del penado, acuerde que la responsabilidad subsidiaria se cumpla mediante trabajos en beneficio de la comunidad:', o:{a:'Cada día de privación de libertad equivaldrá a dos jornadas de trabajo.',b:'Cada día de privación de libertad equivaldrá a una jornada de trabajo.',c:'Cada día de privación de libertad equivaldrá a tres jornadas de trabajo.',d:'Los trabajos en beneficio de la comunidad no pueden acordarse como responsabilidad subsidiaria.'}, correct:'b', why:{b:'El art.53 CP establece que cada día de privación de libertad equivale a una jornada de trabajo en beneficio de la comunidad.'}},
{n:254, q:'En los supuestos de multa proporcional, los Jueces y Tribunales establecerán, según su prudente arbitrio, la responsabilidad personal subsidiaria que proceda, que no podrá exceder, en ningún caso, de:', o:{a:'Un año de duración.',b:'Dos años de duración.',c:'Tres años de duración.',d:'Cinco años de duración.'}, correct:'a', why:{a:'La responsabilidad personal subsidiaria en multa proporcional no puede exceder de 1 año (art.53.3 CP).'}},
{n:255, q:'Según establece el art.53 del Código Penal, la responsabilidad subsidiaria no se impondrá:', o:{a:'A los condenados a pena privativa de libertad superior a ocho años.',b:'A los condenados a pena privativa de libertad superior a cinco años.',c:'A los condenados a pena privativa de libertad superior a tres años.',d:'A los condenados a pena privativa de libertad superior a dos años.'}, correct:'a', why:{a:'El art.53.3 CP establece que la responsabilidad subsidiaria no se impondrá a los condenados a pena privativa de libertad superior a ocho años.'}},
{n:256, q:'Según establecido el art.53 del Código Penal, respecto a la pena de multa, indique la afirmación incorrecta:', o:{a:'El cumplimiento de la responsabilidad subsidiaria extingue la obligación de pago de la multa, aunque mejore la situación económica del penado.',b:'Si el condenado no satisficiere, voluntariamente o por vía de apremio la multa impuesta, en ningún caso podrá cumplirse mediante localización permanente.',c:'Podrá ser fraccionado el pago de la multa impuesta a una persona jurídica, durante un período de hasta cinco años, cuando su cuantía ponga probablemente en peligro la supervivencia de aquélla o el mantenimiento de los puestos de trabajo existentes en la misma, o cuando lo aconseje el interés general.',d:'Si la persona jurídica condenada no satisficiere, voluntariamente o por vía de apremio, la multa impuesta en el plazo que se hubiere señalado, el Tribunal podrá acordar su intervención hasta el pago total de la misma.'}, correct:'b', why:{b:'En delitos leves, el impago de multa SÍ puede cumplirse mediante localización permanente, siendo incorrecta la opción b.'}},
{n:257, q:'Las penas accesorias se regulan en el Código Penal:', o:{a:'En la Sección 5, del Capítulo I, del Título III del Libro I.',b:'En la Sección 4, del Capítulo I, del Título II del Libro II.',c:'En la Sección 3, del Capítulo I, del Título III del Libro I.',d:'En la Sección 2, del Capítulo I, del Título III del Libro II.'}, correct:'a', why:{a:'Las penas accesorias se regulan en la Sección 5 del Capítulo I del Título III del Libro I del CP.'}},
{n:258, q:'Las penas accesorias reguladas en el Código Penal:', o:{a:'Abarcan los artículos 64 a 67.',b:'Abarcan los artículos 64 a 69.',c:'Abarcan los artículos 54 a 57.',d:'Abarcan los artículos 51 a 67.'}, correct:'c', why:{c:'Las penas accesorias están reguladas en los artículos 54 a 57 del CP.'}},
{n:259, q:'Según dispones el art.54 del Código Penal, las penas de inhabilitación son accesorias:', o:{a:'En todo caso.',b:'En los casos en que, no imponiéndolas especialmente, la Ley declare que otras penas las llevan consigo.',c:'En todo caso, salvo que la ley disponga expresamente lo contrario.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'Las inhabilitaciones son accesorias cuando la ley declara que otras penas las llevan consigo sin imponerlas especialmente (art.54 CP).'}},
{n:260, q:'Llevará consigo la inhabilitación absoluta durante el tiempo de la condena, salvo que ésta ya estuviere prevista como pena principal para el supuesto de que se trate.', o:{a:'La pena de prisión igual o superior a diez años.',b:'La pena de prisión igual o superior a ocho años.',c:'La pena de prisión igual o superior a cinco años.',d:'La pena de prisión igual o superior a tres años.'}, correct:'a', why:{a:'La prisión igual o superior a 10 años lleva consigo inhabilitación absoluta durante la condena (art.55 CP).'}},
{n:261, q:'El Juez podrá imponer, además de la inhabilitación especial para el ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento, bien la privación de la patria potestad:', o:{a:'A los condenados a pena de prisión por tiempo igual o superior a diez años.',b:'Cuando estos derechos hubieren tenido relación directa con el delito cometido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La privación de patria potestad como accesoria puede imponerse cuando dichos derechos tuvieron relación directa con el delito (art.56 CP).'}},
{n:262, q:'En las penas de prisión inferiores a diez años, los jueces o tribunales impondrán, atendiendo a la gravedad del delito, como penas accesorias:', o:{a:'Suspensión de empleo o cargo público.',b:'Inhabilitación especial para el derecho de sufragio pasivo durante el tiempo de la condena.',c:'Inhabilitación especial para empleo o cargo público, profesión, oficio, industria, comercio, ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento o cualquier otro derecho, la privación de la patria potestad, si estos derechos hubieren tenido relación directa con el delito cometido.',d:'Alguna o algunas de las penas citadas en las respuestas anteriores.'}, correct:'d', why:{d:'En prisión inferior a 10 años se impondrán las accesorias que sean adecuadas según la gravedad del delito (art.56 CP).'}},
{n:263, q:'La vinculación prevista en los artículos 55 y 56 del Código Penal, respecto de una pena principal con las penas accesorias:', o:{a:'Deberá determinarse expresamente en la sentencia.',b:'Deberá aplicarse conforme a las reglas establecidas en el art.479 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La vinculación de la pena accesoria con la principal debe determinarse expresamente en la sentencia.'}},
{n:264, q:'Las autoridades judiciales, atendiendo a la gravedad de los hechos o al peligro que el delincuente represente, podrán acordar en sus sentencias la imposición de una o varias de las prohibiciones contempladas en el art.48 del Código Penal por un tiempo que no excederá del tiempo previsto en el art.57 del CP, cuando se trate de:', o:{a:'Delitos de homicidio, aborto, lesiones, contra la libertad, de torturas y contra la integridad moral o trata de seres humanos.',b:'Delitos contra la libertad e indemnidad sexuales, la intimidad, el derecho a la propia imagen o la inviolabilidad del domicilio.',c:'Delitos contra el honor, el patrimonio, el orden socioeconómico o las relaciones familiares.',d:'Cualquiera de los delitos descritos en las respuestas anteriores.'}, correct:'d', why:{d:'El art.57 CP permite imponer prohibiciones del art.48 en todos esos tipos de delitos.'}},
{n:265, q:'Según el art.57 del Código Penal, las prohibiciones contempladas en el art.48 de este código, cuando se trate de delitos de homicidio, aborto, lesiones, contra la libertad, de torturas y contra la integridad moral o trata de seres humanos, podrán imponerse...', o:{a:'Por un tiempo que no excederá de diez años si el delito fuera grave, o de cinco si fuera menos grave.',b:'Por un tiempo que no excederá de ocho años si el delito fuera grave, o de cinco si fuera menos grave.',c:'Por un tiempo que no excederá de cinco años si el delito fuera grave, o de tres si fuera menos grave.',d:'Por un tiempo que no excederá de tres años si el delito fuera grave, o de dos si fuera menos grave.'}, correct:'a', why:{a:'El art.57.1 CP establece que las prohibiciones pueden imponerse por hasta 10 años si el delito es grave, o 5 si es menos grave.'}},
{n:266, q:'Según el art.57 del Código Penal, las prohibiciones contempladas en el art.48 de este código, cuando se trate de delitos contra la libertad e indemnidad sexuales, la intimidad, el derecho a la propia imagen o la inviolabilidad del domicilio, podrán imponerse...', o:{a:'Por un tiempo que no excederá de diez años si el delito fuera grave, o de cinco si fuera menos grave.',b:'Por un tiempo que no excederá de ocho años si el delito fuera grave, o de cinco si fuera menos grave.',c:'Por un tiempo que no excederá de cinco años si el delito fuera grave, o de tres si fuera menos grave.',d:'Por un tiempo que no excederá de tres años si el delito fuera grave, o de dos si fuera menos grave.'}, correct:'a', why:{a:'El art.57.1 CP establece el mismo límite de 10 años (grave) o 5 años (menos grave) para estos delitos.'}},
{n:267, q:'Según el art.57 del Código Penal, las prohibiciones contempladas en el art.48 de este código, cuando se trate de delitos contra el honor, el patrimonio, el orden socioeconómico o las relaciones familiares, podrán imponerse...', o:{a:'Por un tiempo que no excederá de diez años si el delito fuera grave, o de cinco si fuera menos grave.',b:'Por un tiempo que no excederá de ocho años si el delito fuera grave, o de cinco si fuera menos grave.',c:'Por un tiempo que no excederá de cinco años si el delito fuera grave, o de tres si fuera menos grave.',d:'Por un tiempo que no excederá de tres años si el delito fuera grave, o de dos si fuera menos grave.'}, correct:'a', why:{a:'El art.57.1 CP establece los mismos límites (10 años/grave, 5 años/menos grave) para estos delitos.'}},
{n:268, q:'Cuando se trate de delitos y contra personas descritos en el art.57 del Código Penal, apartados 1 y 2 respectivamente, la prohibición de aproximarse a la víctima, o a aquellos de sus familiares u otras personas que determine el juez o tribunal:', o:{a:'Podrá aplicarse por el tiempo que se establezca en la sentencia.',b:'Podrá aplicarse, sin perjuicio de lo establecido en otros preceptos del CP.',c:'Podrá aplicarse durante el tiempo de la condena.',d:'Se aplicará, en todo caso.'}, correct:'d', why:{d:'El art.57.2 CP establece que la prohibición de aproximarse se aplicará en todo caso cuando la víctima sea una de las personas del art.173.2 CP.'}},
{n:269, q:'Cuando se trate de delitos y contra personas descritos en el art.57 del Código Penal, apartados 1 y 2 respectivamente, la prohibición de aproximarse a la víctima, o a aquellos de sus familiares u otras personas que determine el juez o tribunal:', o:{a:'Se podrá aplicar por un tiempo que no excederá de diez años si el delito fuera grave, o de cinco si fuera menos grave, sin perjuicio de lo dispuesto en otros preceptos del CP, respecto de la imposición de estas penas.',b:'Se aplicará, en todo caso, por un tiempo que no excederá de diez años si el delito fuera grave, o de cinco si fuera menos grave, sin perjuicio de lo dispuesto en otros preceptos del CP, respecto de la imposición de estas penas.',c:'Se podrá aplicar por un tiempo que no excederá de cinco años si el delito fuera grave, o de tres si fuera menos grave.',d:'Se aplicará, en todo caso, por un tiempo que no excederá de cinco años si el delito fuera grave, o de tres si fuera menos grave.'}, correct:'b', why:{b:'El art.57.2 CP establece que la prohibición se aplicará en todo caso, por hasta 10 años (grave) o 5 años (menos grave).'}},
{n:270, q:'Las prohibiciones contempladas en el art.48 del Código Penal, aplicables a los delitos que expresamente indica el art.57 de este código, cuando los mismos sean calificados leves, se impondrán:', o:{a:'Por un periodo de tiempo que no excederá de tres meses.',b:'Por un periodo de tiempo que no excederá de seis meses.',c:'Por un periodo de tiempo que no excederá de un año.',d:'Por un periodo de tiempo que no excederá de dieciocho meses.'}, correct:'c', why:{c:'Para delitos leves, las prohibiciones del art.48 CP se impondrán por un periodo que no excederá de 1 año (art.57.3 CP).'}},
{n:271, q:'Las medidas de seguridad están reguladas en el Código Penal, en ...', o:{a:'El Libro I.',b:'El Libro II.',c:'El Título Preliminar.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'Las medidas de seguridad están reguladas en el Libro I del Código Penal.'}},
{n:272, q:'El Código Penal regula las medidas de seguridad:', o:{a:'En el Título VI, del Libro II, artículos 108 a 129.',b:'En el Título V, del Libro II, artículos 110 a 118.',c:'En el Título IV, del Libro I, artículos 95 a 108.',d:'En el Título V, del Libro I, artículos 110 a 118.'}, correct:'c', why:{c:'Las medidas de seguridad se regulan en el Título IV del Libro I, artículos 95 a 108 del CP.'}},
{n:273, q:'Respecto a las medidas de seguridad reguladas en el Código Penal, indique la afirmación incorrecta:', o:{a:'Las medidas de seguridad se justifican en la peligrosidad del sujeto que haya incurrido en la comisión de algún delito, con el objetivo de lograr su reeducación y reinserción social.',b:'Según el artículo 6 del Código Penal, las medidas de seguridad deben ser proporcionales a la peligrosidad criminal del sujeto al que se le impongan.',c:'No pueden ser nunca más gravosas ni de mayor duración que la pena que se aplicaría al mismo sujeto en caso de ser condenado por el hecho cometido.',d:'Pueden exceder su duración límite solo en los casos previstos en el artículo 17 del Código Penal'}, correct:'d', why:{d:'La afirmación incorrecta es la d: las medidas de seguridad no pueden superar su duración límite según el art.6 CP, y no hay excepción en el art.17 CP para ello.'}},
{n:274, q:'Las medidas de seguridad:', o:{a:'Deben ser proporcionales a la peligrosidad criminal del sujeto al que se le impongan, y no pueden ser nunca más gravosas ni de mayor duración que la pena que se aplicaría al mismo sujeto en caso de ser condenado por el hecho cometido, ni exceder el límite de lo necesario para prevenir su peligrosidad.',b:'Se aplicarán por el Juez o Tribunal cuando concurra alguna circunstancia eximente de responsabilidad criminal de los apartados 1, 2 y 3 del artículo 20 CP, ya sea de manera completa o incompleta.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Las medidas de seguridad son proporcionales, no superan la pena aplicable y se aplican cuando concurren eximentes de los aptos 1, 2 y 3 del art.20 CP (art.95 CP).'}},
{n:275, q:'Las medidas de seguridad se aplicarán por el Juez o Tribunal, previos los informes que estime convenientes, a las personas que se encuentren en los supuestos previstos en el Código Penal...', o:{a:'Cuando concurra alguna circunstancia eximente de responsabilidad criminal de los apartados 1, 2 y 3 del artículo 20 CP, ya sea de manera completa o incompleta.',b:'Cuando concurra alguna circunstancia eximente de responsabilidad criminal de los apartados 1, 2 y 3 del artículo 20 CP, ya sea de manera completa.',c:'Cuando el hecho y de las circunstancias personales del sujeto pueda deducirse un pronóstico de comportamiento futuro que revele la probabilidad de comisión de nuevos delitos.',d:'Cuando concurra alguna de las mencionadas en la respuesta a), siempre que concurran las circunstancias descritas en las respuestas b) y c).'}, correct:'d', why:{d:'Las medidas de seguridad se aplican cuando concurre una eximente (completa o incompleta) y se prevé peligrosidad de comisión futura (art.95 CP).'}},
{n:276, q:'Cuando la pena que hubiere podido imponerse por el delito cometido no fuere privativa de libertad...', o:{a:'El juez o tribunal sentenciador sólo podrá acordar alguna o algunas de las medidas previstas en el artículo 96.3. del Código Penal.',b:'El juez o tribunal sentenciario deberá acordar alguna o algunas de las medidas previstas en el artículo 96.1. del Código Penal.',c:'El juez o tribunal sentenciador deberá acordar una de las medidas previstas en el artículo 96.3. del Código Penal.',d:'El juez o tribunal sentenciador sólo podrá acordar una de las medidas previstas en el artículo 96.1. del Código Penal.'}, correct:'a', why:{a:'Cuando el delito no tiene pena privativa de libertad, el juez solo podrá acordar medidas no privativas de libertad del art.96.3 CP.'}},
{n:277, q:'Las medidas de seguridad que se pueden imponer con arreglo al Código Penal:', o:{a:'Se clasifican en privativas o no privativas de libertad.',b:'Se clasifican en restrictivas o limitativas de derechos.',c:'Se clasifican en graves, menos graves y leves.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Las medidas de seguridad se clasifican en privativas y no privativas de libertad (art.96 CP).'}},
{n:278, q:'Según el Código Penal, es una medida de seguridad privativa de libertad:', o:{a:'El internamiento en un centro psiquiátrico.',b:'El internamiento en un centro de deshabituación.',c:'El internamiento en un centro educativo especial.',d:'Las tres citadas en las respuestas anteriores son medidas privativas de libertad.'}, correct:'d', why:{d:'El internamiento en centro psiquiátrico, de deshabituación y educativo especial son las tres medidas privativas de libertad (art.96.1 CP).'}},
{n:279, q:'Según el Código Penal, es una medida de seguridad no privativa de libertad:', o:{a:'La inhabilitación profesional.',b:'El destierro.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La inhabilitación profesional es medida de seguridad no privativa de libertad (art.96.3 CP). El destierro no es medida de seguridad.'}},
{n:280, q:'Según el Código Penal, es una medida de seguridad no privativa de libertad:', o:{a:'La expulsión del territorio nacional de extranjeros no residentes legalmente en España.',b:'La prohibición de aproximarse a la víctima o a aquellos de sus familiares o personas que determine el Juez o Tribunal.',c:'La localización permanente.',d:'Los trabajos en beneficio de la comunidad.'}, correct:'a', why:{a:'La expulsión del territorio nacional de extranjeros no residentes es medida de seguridad no privativa de libertad (art.96.3 CP).'}},
{n:281, q:'La expulsión del territorio nacional de extranjeros no residentes legalmente en España', o:{a:'Es una medida de seguridad no privativa de libertad.',b:'Implica que no podrán regresar a nuestro país en un plazo de 10 años, contados desde la fecha de su expulsión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La expulsión del territorio es medida de seguridad no privativa de libertad según el art.96.3.h CP.'}},
{n:282, q:'Según el Código Penal, es una medida de seguridad no privativa de libertad:', o:{a:'La libertad vigilada.',b:'La custodia familiar.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Tanto la libertad vigilada como la custodia familiar son medidas de seguridad no privativas de libertad (art.96.3 CP).'}},
{n:283, q:'Según el art.106 del Código Penal, la libertad vigilada, impuesta como medida de seguridad no privativa de libertad, consistirá:', o:{a:'En el sometimiento del condenado a control judicial a través del cumplimiento por su parte de alguna o algunas de las medidas establecidas en este artículo.',b:'En la aceptación del condenado al cumplimiento de las medidas establecidas para ello en el art.95 del CP.',c:'En la aceptación del condenado al cumplimiento de las medidas establecidas para ello en el art.104 del CP.',d:'En la aceptación del condenado al cumplimiento de las medidas establecidas para ello en el art.96 del CP.'}, correct:'a', why:{a:'La libertad vigilada consiste en el sometimiento del condenado a control judicial mediante el cumplimiento de medidas del art.106 CP.'}},
{n:284, q:'La libertad vigilada, impuesta como medida de seguridad no privativa de libertad, podrá consistir, para el condenado a ella, en el cumplimiento de:', o:{a:'La obligación de estar siempre localizable mediante aparatos electrónicos que permitan su seguimiento permanente.',b:'La obligación de presentarse periódicamente en el lugar que el Juez o Tribunal establezca.',c:'La obligación de comunicar inmediatamente, en el plazo máximo y por el medio que el Juez o Tribunal señale a tal efecto, cada cambio del lugar de residencia o del lugar o puesto de trabajo.',d:'Alguna de las medidas descritas en las respuestas anteriores.'}, correct:'d', why:{d:'La libertad vigilada puede consistir en cualquiera de esas obligaciones según el art.106 CP.'}},
{n:285, q:'La libertad vigilada, impuesta como medida de seguridad no privativa de libertad, podrá consistir, para el condenado a ella, en el cumplimiento de:', o:{a:'La prohibición de desempeñar las actividades que puedan incitarle a cometer hechos delictivos.',b:'La obligación de presentarse ante la Policía en el lugar que el Juez o Tribunal establezca.',c:'La prohibición de ausentarse del lugar donde resida o de un determinado territorio sin autorización del Juez o Tribunal.',d:'Alguna de las medidas descritas en las respuestas anteriores.'}, correct:'d', why:{d:'La libertad vigilada puede incluir cualquiera de esas restricciones según el art.106 CP.'}},
{n:286, q:'La libertad vigilada, impuesta como medida de seguridad no privativa de libertad, podrá consistir, para el condenado a ella, en el cumplimiento de:', o:{a:'La prohibición de aproximarse a la víctima, o a aquellos de sus familiares u otras personas que determine el Juez o Tribunal.',b:'La prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el Juez o Tribunal.',c:'Una o ambas de las medidas descritas en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'La libertad vigilada puede incluir prohibición de aproximarse o comunicarse con la víctima (art.106 CP).'}},
{n:287, q:'La libertad vigilada, impuesta como medida de seguridad no privativa de libertad, podrá consistir, para el condenado a ella, en el cumplimiento de:', o:{a:'La prohibición de acudir a determinados territorios, lugares o establecimientos.',b:'La prohibición de residir en determinados lugares.',c:'La prohibición de desempeñar determinadas actividades que puedan ofrecerle o facilitarle la ocasión para cometer delitos de similar naturaleza.',d:'Alguna o algunas de las medidas descritas en las respuestas anteriores.'}, correct:'d', why:{d:'La libertad vigilada puede incluir cualquiera de esas prohibiciones (art.106 CP).'}},
{n:288, q:'La libertad vigilada, impuesta como medida de seguridad no privativa de libertad, podrá consistir, para el condenado a ella, en el cumplimiento de:', o:{a:'La obligación de participar en programas formativos, laborales, culturales, de educación sexual u otros similares.',b:'La obligación de seguir tratamiento médico externo, o de someterse a un control médico periódico.',c:'Una o ambas de las medidas descritas en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'La libertad vigilada puede incluir obligación de participar en programas formativos o seguir tratamiento médico (art.106 CP).'}},
{n:289, q:'La custodia familiar, impuesta como medida de seguridad no privativa de libertad, implica:', o:{a:'Que el sometido a esta medida quedará sujeto al cuidado y vigilancia del familiar que se designe y que acepte la custodia, quien la ejercerá en relación con el Juez de Vigilancia Penitenciaria y sin menoscabo de las actividades escolares o laborales del custodiado.',b:'Que el sometido a esta medida quedará sujeto al cuidado y vigilancia del familiar que se designe y que acepte la custodia, quien la ejercerá sin menoscabo de las actividades escolares o laborales del custodiado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La custodia familiar implica que el familiar designado la ejerce en relación con el JVP y sin menoscabo de las actividades del custodiado (art.108 CP).'}},
{n:290, q:'Según el Código Penal, es una medida de seguridad no privativa de libertad:', o:{a:'Los trabajos en beneficio de la comunidad.',b:'La privación del derecho a conducir vehículos a motor y ciclomotores.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Ni los trabajos en beneficio de la comunidad ni la privación del derecho a conducir son medidas de seguridad; son penas privativas de derechos.'}},
{n:291, q:'Según el Código Penal, es una medida de seguridad no privativa de libertad:', o:{a:'La privación de la patria potestad.',b:'La privación del derecho a la tenencia y porte de armas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La privación de la patria potestad y del derecho a la tenencia de armas son penas, no medidas de seguridad.'}},
{n:292, q:'Según el Código Penal, es una medida de seguridad no privativa de libertad:', o:{a:'La prohibición de aproximarse a la víctima o a aquellos de sus familiares o personas que determine el Juez o Tribunal.',b:'La localización permanente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La prohibición de aproximarse a la víctima puede ser medida de seguridad no privativa de libertad (art.96.3 CP).'}},
{n:293, q:'Cuando imponga una de las medidas privativas de libertad previstas en el Código Penal o durante la ejecución de la misma, el Juez o Tribunal podrá imponer razonablemente la medida de libertad vigilada o la de custodia familiar, o ambas:', o:{a:'Por un tiempo no superior a diez años.',b:'Por un tiempo no superior a cinco años.',c:'Por un tiempo no superior a tres años.',d:'Por un tiempo comprendido entre seis meses y tres años.'}, correct:'b', why:{b:'Al imponer medida privativa de libertad, el juez puede añadir libertad vigilada o custodia familiar por un máximo de 5 años (art.107 CP).'}},
{n:294, q:'Cuando imponga una de las medidas privativas de libertad previstas en el Código Penal o durante la ejecución de la misma, el Juez o Tribunal podrá imponer razonablemente, por un tiempo de hasta diez años, la medida de:', o:{a:'Libertad vigilada, cuando expresamente lo disponga este Código.',b:'La privación del derecho a la tenencia y porte de armas.',c:'La privación del derecho a conducir vehículos a motor y ciclomotores.',d:'Podrá imponer una o varias de las citadas en las respuestas anteriores.'}, correct:'a', why:{a:'Junto a medidas privativas de libertad, puede imponerse libertad vigilada por hasta 10 años cuando el CP lo disponga expresamente (art.105 CP).'}},
{n:295, q:'Durante la ejecución de la sentencia, el Juez o Tribunal sentenciador de una medida de seguridad, adoptará alguna de las decisiones establecidas en el art.97 del Código Penal, siendo una de ellas:', o:{a:'Decretar el cese de cualquier medida de seguridad impuesta en cuanto desaparezca la peligrosidad criminal del sujeto.',b:'Sustituir una medida de seguridad por otra que estime más adecuada, entre las previstas para el supuesto de que se trate. En el caso de que fuera acordada la sustitución, y el sujeto evolucionara desfavorablemente, se dejará sin efecto la sustitución, volviéndose a aplicar la medida sustituida.',c:'Dejar en suspenso la ejecución de la medida en atención al resultado ya obtenido con su aplicación, por un plazo no superior al que reste hasta el máximo señalado en la sentencia que lo impuso. La suspensión quedará condicionada a que el sujeto no delinca durante el plazo fijado, y podrá dejarse sin efecto si nuevamente resultara acreditada cualquiera de las circunstancias previstas en el art.95 del CP.',d:'Todas las decisiones descritas en las respuestas anteriores están establecidas en el art.97 del CP.'}, correct:'d', why:{d:'El art.97 CP establece todas esas decisiones que puede adoptar el juez durante la ejecución de la medida de seguridad.'}},
{n:296, q:'Según lo establecido en el art.97 del Código Penal, mantener la ejecución de la medida de seguridad impuesta...', o:{a:'Es una de las decisiones que adoptará, durante la ejecución de la sentencia, el Juez o Tribunal sentenciador.',b:'Deberá ser la opción prioritaria cuando se trate de medidas no privativas de libertad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Mantener la ejecución de la medida de seguridad es una de las decisiones que puede adoptar el juez durante la ejecución (art.97 CP).'}},
{n:297, q:'A los efectos de adoptar una decisión de las establecidas en el art.97 del Código Penal, cuando se trate de una medida de seguridad privativa de libertad o de una medida de libertad vigilada que deba ejecutarse después del cumplimiento de una pena privativa de libertad, el Juez de Vigilancia Penitenciaria estará obligado a:', o:{a:'A elevar, al menos trimestralmente, una propuesta de mantenimiento, cese, sustitución o suspensión de la misma.',b:'A elevar, al menos semestralmente, una propuesta de mantenimiento, cese, sustitución o suspensión de la misma.',c:'A elevar, al menos anualmente, una propuesta de mantenimiento, cese, sustitución o suspensión de la misma.',d:'A elevar, cada año, una propuesta de ejecución, mantenimiento, sustitución o suspensión de la misma.'}, correct:'b', why:{b:'El JVP debe elevar al menos semestralmente una propuesta sobre la medida de seguridad privativa de libertad (art.98 CP).'}},
{n:298, q:'A los efectos de adoptar una decisión de las establecidas en el art.97 del Código Penal, cuando se trate de una medida de seguridad no privativa de libertad, distinta de la de libertad vigilada, el Juez o Tribunal sentenciador recabará directamente de las Administraciones, facultativos y profesionales establecidos para ello:', o:{a:'Los oportunos informes acerca de la situación y la evolución del condenado.',b:'Los oportunos informes acerca del grado de rehabilitación y el pronóstico de reincidencia o reiteración delictiva del condenado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Para medidas no privativas de libertad, el juez recaba informes sobre la situación, evolución y pronóstico de reincidencia del condenado (art.98 CP).'}},
{n:299, q:'De conformidad con lo dispuesto en el artículo 100 del Código Penal:', o:{a:'El quebrantamiento de una medida de seguridad de internamiento dará lugar a que el juez o tribunal ordene el reingreso del sujeto en el mismo centro del que se hubiese evadido o en otro que corresponda a su estado.',b:'En el quebrantamiento de una medida de seguridad distinta al internamiento, el juez o tribunal podrá acordar la sustitución de la quebrantada por la de internamiento si ésta estuviese prevista para el supuesto de que se trate y si el quebrantamiento demostrase su necesidad.',c:'En el quebrantamiento de una medida de seguridad, el Juez o Tribunal deducirá testimonio por el quebrantamiento.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.100 CP establece todas esas consecuencias para el quebrantamiento de medidas de seguridad.'}},
{n:300, q:'De conformidad con lo dispuesto en el artículo 100 del Código Penal, respecto al quebrantamiento de una medida de seguridad....', o:{a:'No se considerará quebrantamiento la negativa del sujeto a someterse a tratamiento médico inicialmente consentido.',b:'En caso de negativa del sujeto a iniciar o a continuar un tratamiento médico, el Juez o tribunal podrá acordar la sustitución del tratamiento inicial o posteriormente rechazado por otra medida de entre las aplicables al supuesto de que se trate y si el quebrantamiento demostrase su necesidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.100 CP establece que la negativa a tratamiento médico no es quebrantamiento, y que el juez puede sustituir el tratamiento rechazado por otra medida.'}},
];
